(() => {
  'use strict';
  const app = document.getElementById('app');
  const overlay = document.getElementById('overlay-root');
  const toastRoot = document.getElementById('toast-root');
  const state = { me:null, drives:[], catalog:[], departments:[] };
  const DEFAULT_BRAND = '#813DF5';
  const SAFE = new Set(['GET','HEAD','OPTIONS','TRACE']);

  const esc = (v='') => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const attr = esc;
  const fmtDate = v => { if(!v) return '—'; const d=new Date(v); return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}); };
  const fmtDateTime = v => { if(!v) return '—'; const d=new Date(v); return Number.isNaN(d.getTime())?esc(v):d.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}); };
  const score = v => v===null||v===undefined||Number.isNaN(Number(v)) ? '—' : String(Math.round(Number(v)));
  const initials = (name, fallback='C') => (String(name||'').trim().split(/\s+/).map(x=>x[0]).filter(Boolean).slice(0,2).join('').toUpperCase() || fallback);
  const statusLabel = s => String(s||'—').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
  const statusTone = s => { const x=String(s||'').toLowerCase(); if(/released|active|ready|eligible|shortlist|open|complete/.test(x))return'green'; if(/scheduled|hold|upcoming|review|draft|develop/.test(x))return'amber'; if(/reject|cancel|error|not eligible|not ready/.test(x))return'red'; return'neutral'; };
  const statusPill = (s,tone) => `<span class="status-pill ${tone||statusTone(s)}">${esc(statusLabel(s))}</span>`;
  const packageLabel = d => { const a=d.package_min_lpa,b=d.package_max_lpa; if(a==null&&b==null)return'—'; if(a===b)return`₹${a} LPA`; return `₹${a??'—'}–${b??'—'} LPA`; };
  const windowState = d => { const a=d.window_start_at||d.window_start,b=d.window_end_at||d.window_end;if(!a||!b)return'not configured';const now=Date.now(),s=Date.parse(a),e=Date.parse(b);if(!Number.isFinite(s)||!Number.isFinite(e))return'not configured';if(now<s)return'upcoming';if(now>e)return'ended';return'open';};
  const qs = sel => document.querySelector(sel);
  const qsa = sel => [...document.querySelectorAll(sel)];
  function cookie(name){const p=encodeURIComponent(name)+'=';const m=document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(p));return m?decodeURIComponent(m.slice(p.length)):''}
  class ApiError extends Error{constructor(status,message,code){super(message);this.status=status;this.code=code}}
  async function api(path,{method='GET',body,headers={}}={}){
    method=method.toUpperCase(); const isForm=body instanceof FormData; const h={'X-Portal-Role':'admin',...headers}; if(body!==undefined&&!isForm)h['Content-Type']='application/json'; if(!SAFE.has(method)){const csrf=cookie('vd_admin_csrf');if(csrf)h['X-CSRF-Token']=csrf}
    const ctrl=new AbortController(),tm=setTimeout(()=>ctrl.abort(),25000); let res;
    const request={method,headers:h,credentials:'include',signal:ctrl.signal};if(body!==undefined)request.body=isForm?body:JSON.stringify(body);
    try{res=await fetch(path,request)}catch(e){throw new ApiError(0,e.name==='AbortError'?'The request timed out. Check your connection and try again.':'Could not reach the server. Check your connection and try again.')}finally{clearTimeout(tm)}
    const type=res.headers.get('content-type')||''; if(res.ok&&!type.includes('application/json')) return res; const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{}
    if(!res.ok){const detail=data?.detail; const validation=Array.isArray(detail)?detail.map(x=>x?.msg||x?.message).filter(Boolean).join(' '):''; const msg=typeof detail==='string'?detail:validation||detail?.message||({401:'Your session has expired. Please sign in again.',403:'You do not have permission to do that.',404:'That could not be found.',409:'That conflicts with the current state. Refresh and try again.',422:'Some of the information provided was invalid.',429:'Too many attempts. Please wait and try again.',500:'Something went wrong on the server. Please try again.'}[res.status]||`Request failed (${res.status}).`); throw new ApiError(res.status,msg,detail?.code)} return data;
  }
  function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3500)}
  function tint(hex,amount){const c=hex.replace('#','');if(!/^[0-9a-f]{6}$/i.test(c))return hex;const vals=[0,2,4].map(i=>parseInt(c.slice(i,i+2),16));return '#'+vals.map(v=>Math.round(v+(255-v)*amount).toString(16).padStart(2,'0')).join('')}
  function contrast(hex){const c=hex.replace('#','');if(!/^[0-9a-f]{6}$/i.test(c))return'#fff';const [r,g,b]=[0,2,4].map(i=>parseInt(c.slice(i,i+2),16));return (r*299+g*587+b*114)/1000>158?'#15142d':'#fff'}
  function applyBrand(){const color=/^#[0-9a-f]{6}$/i.test(state.me?.primary_color||'')?state.me.primary_color:DEFAULT_BRAND;const r=document.documentElement.style;r.setProperty('--brand',color);r.setProperty('--brand-hover',tint(color,.14));r.setProperty('--brand-strong',color);r.setProperty('--brand-soft',tint(color,.92));r.setProperty('--brand-softer',tint(color,.965));r.setProperty('--brand-border',tint(color,.76));r.setProperty('--brand-focus',tint(color,.82));r.setProperty('--brand-contrast',contrast(color));}

  function routeInfo(){const raw=(location.hash||'#/overview').slice(1);const [pathPart,q='']=raw.split('?');return {path:pathPart||'/overview',params:new URLSearchParams(q)};}
  function go(path){location.hash='#'+path}
  function empty(title,copy,action=''){return `<div class="surface empty-state"><div class="empty-mark">◎</div><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`}
  function field(label,input,help=''){return `<label class="field-label">${esc(label)}${input}${help?`<span class="field-help">${esc(help)}</span>`:''}</label>`}
  function metric(label,value,note){return `<div class="surface metric-card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
  function sectionTitle(title,copy='',right=''){return `<div class="section-title"><div><h3>${esc(title)}</h3>${copy?`<p>${esc(copy)}</p>`:''}</div>${right}</div>`}

  function navLink(path,label,icon,current){const active=current===path||(path!='/overview'&&current.startsWith(path));return `<a class="side-link ${active?'active':''}" href="#${path}"><span class="nav-icon">${icon}</span><span>${esc(label)}</span></a>`}
  function shell({eyebrow='',title='',description='',actions='',body=''}){const me=state.me,current=routeInfo().path,college=me?.college_name||'College',user=me?.user?.full_name||'College User',role='College';return `<div class="placement-app"><button id="nav-scrim" class="nav-scrim" aria-label="Close navigation"></button><aside id="sidebar" class="app-sidebar"><div class="sidebar-brand-wrap"><a class="wordmark" href="#/overview"><img src="/voicedotslogo.svg" alt="" width="30" height="30" /><span>oiceDots</span></a><div class="college-identity"><div class="college-logo">${me?.logo_url?`<img src="${attr(me.logo_url)}" alt=""/>`:esc(initials(college))}</div><div><strong>${esc(college)}</strong><span>College Placement portal</span></div></div></div><nav class="side-nav"><div class="nav-section-label">Workspace</div>${navLink('/overview','Overview','⌂',current)}${navLink('/drives','Placement Drives','▦',current)}${navLink('/reports','Interview Reports','▤',current)}${navLink('/readiness','Readiness Index','◈',current)}<div class="nav-section-label">Students</div>${navLink('/students','Student Directory','○',current)}${navLink('/students/import','Import Students','↑',current)}<div class="nav-section-label">Configuration</div>${navLink('/academic','Academic Setup','▥',current)}${navLink('/agents','Interview Agents','🎙',current)}${navLink('/settings','College Settings','⚙',current)}</nav><div class="sidebar-footer"><div class="student-mini"><div class="avatar">${esc(initials(user,'CL'))}</div><div><strong>${esc(user)}</strong><span>${esc(role)}</span></div></div><button id="desktop-logout-btn" class="button button--secondary button--full" type="button">Sign out</button></div></aside><div class="app-content"><header class="mobile-topbar admin-topbar"><button id="menu-btn" class="icon-button mobile-menu">☰</button><a class="wordmark" href="#/overview"><img src="/voicedotslogo.svg" alt="" width="30" height="30" /><span>oiceDots</span></a><div class="top-actions"><span class="date-chip">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><button id="logout-btn" class="icon-button" aria-label="Sign out">↗</button></div></header><main class="page-root"><header class="page-header"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}${title?`<h1>${esc(title)}</h1>`:''}${description?`<p>${esc(description)}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</header>${body}</main></div></div>`}
  function bindShell(){qs('#logout-btn')?.addEventListener('click',logout);qs('#desktop-logout-btn')?.addEventListener('click',logout);const sidebar=qs('#sidebar'),scrim=qs('#nav-scrim');qs('#menu-btn')?.addEventListener('click',()=>{sidebar?.classList.add('open');scrim?.classList.add('show')});scrim?.addEventListener('click',()=>{sidebar?.classList.remove('open');scrim.classList.remove('show')});}

  async function hydrate(){try{state.me=await api('/api/auth/admin-me');if(state.me?.role!=='admin')state.me=null}catch(e){if(!(e instanceof ApiError)||e.status!==401)console.warn(e);state.me=null}applyBrand();renderRoute()}
  async function logout(){try{await api('/api/auth/admin-logout',{method:'POST'})}catch{}state.me=null;applyBrand();go('/login')}
  function loginPage(){app.innerHTML=`<main class="auth-shell"><section class="auth-brand-panel"><div class="auth-brand-copy"><div class="wordmark wordmark--inverse"><img src="/voicedotslogo.svg" alt="" width="30" height="30" /><span>oiceDots</span></div><div class="auth-kicker">College placement operations</div><h1>From interview evidence to confident placement decisions.</h1><p>Manage campus drives, candidate readiness, AI panel assessments, human decisions, and student result publication in one operating workspace.</p></div><div class="auth-proof-grid"><div><strong>3</strong><span>interviewers + AI proctor</span></div><div><strong>1</strong><span>placement operating system</span></div><div><strong>100%</strong><span>human-controlled decisions</span></div></div></section><section class="auth-form-panel"><form id="login-form" class="auth-card"><div class="mobile-auth-brand wordmark"><img src="/voicedotslogo.svg" alt="" width="30" height="30" /><span>oiceDots</span></div><span class="context-label">College Placement Portal</span><h2>Welcome back</h2><p class="muted">Sign in with your College account.</p><div id="login-error" class="form-error hidden"></div><div class="stack-form">${field('Work email','<input id="login-email" class="field-input" type="email" required autocomplete="username" placeholder="placement@college.edu"/>')}${field('Password','<input id="login-pass" class="field-input" type="password" required autocomplete="current-password" placeholder="Enter your password"/>')}<button id="login-submit" class="button button--primary button--full">Sign in to placement workspace</button></div><p class="portal-switch">Student? <a href="/">Open Student Portal →</a></p></form></section></main>`;qs('#login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=qs('#login-submit'),err=qs('#login-error');btn.disabled=true;btn.textContent='Signing in…';err.classList.add('hidden');try{const res=await api('/api/auth/login',{method:'POST',body:{email:qs('#login-email').value.trim(),password:qs('#login-pass').value}});if(res.user?.role==='student')throw new ApiError(403,'This workspace is for College accounts. Use the Student Portal for student accounts.');state.me=await api('/api/auth/admin-me');applyBrand();go('/overview')}catch(x){err.textContent=x.message||'Could not sign in.';err.classList.remove('hidden')}finally{btn.disabled=false;btn.textContent='Sign in to placement workspace'}})}

  async function loadFoundation(){const jobs=[];if(!state.drives.length)jobs.push(api('/api/college/drives').then(x=>state.drives=x));if(!state.catalog.length)jobs.push(api('/api/college/academic-catalog').then(x=>state.catalog=x.programs||[]).catch(e=>toast(`Could not load academic catalog: ${e.message||'unknown error'}`,'error')));if(!state.departments.length)jobs.push(api('/api/college/departments').then(x=>state.departments=x||[]).catch(e=>toast(`Could not load departments: ${e.message||'unknown error'}`,'error')));await Promise.all(jobs)}
  async function renderOverview(){await loadFoundation();const drives=state.drives;const active=drives.filter(d=>d.status==='active').length,open=drives.filter(d=>windowState(d)==='open').length,assigned=drives.reduce((a,d)=>a+(Number(d.assignment_count)||0),0),eligible=drives.reduce((a,d)=>a+(Number(d.latest_snapshot_eligible_count)||0),0);const rows=drives.slice(0,8).map(d=>`<tr><td><strong>${esc(d.company_name)}</strong><span>${esc(d.role_title)} · ${esc(packageLabel(d))}</span></td><td>${statusPill(d.status)}</td><td>${statusPill(windowState(d),windowState(d)==='open'?'brand':'neutral')}</td><td>${d.latest_snapshot_eligible_count??'—'}</td><td>${d.assignment_count??0}</td><td>${fmtDate(d.drive_date)}</td><td><a class="row-link" href="#/drives/${attr(d.id)}">Open →</a></td></tr>`).join('');app.innerHTML=shell({eyebrow:'Placement operations',title:'Overview',description:'A live operational view of the placement work your backend can prove right now.',actions:'<a class="button button--primary" href="#/drives">Manage drives →</a>',body:`<section class="metric-grid">${metric('Active drives',active,'Current business lifecycle')}${metric('Interview windows open',open,'Live access windows')}${metric('Assigned candidates',assigned,'Across listed drives')}${metric('Eligible candidates',eligible,'Latest drive snapshots')}</section><section class="section-heading"><div><h2>Placement drives</h2><p>Recent and active hiring workflows.</p></div><a class="section-link" href="#/drives">View all</a></section>${rows?`<div class="surface table-shell"><table class="data-table"><thead><tr><th>Company / role</th><th>Status</th><th>Window</th><th>Eligible</th><th>Assigned</th><th>Drive date</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('No placement drives yet','Create the first company drive to start eligibility and interview operations.','<a class="button button--primary" href="#/drives">Create drive</a>')}`});bindShell()}

  async function renderDrives(){await loadFoundation();app.innerHTML=shell({eyebrow:'Placement',title:'Placement Drives',description:'Create and manage company drives, eligibility, interviews, candidate evidence, decisions, and result publication.',actions:'<button id="create-drive" class="button button--primary">+ Create drive</button>',body:`<div class="toolbar surface"><div class="search-field">⌕<input id="drive-search" placeholder="Search company or role…"/></div><div class="segmented" id="drive-filter">${['all','active','draft','closed','cancelled'].map((x,i)=>`<button data-value="${x}" class="${i===0?'active':''}">${statusLabel(x)}</button>`).join('')}</div></div><div id="drive-results"></div>`});bindShell();let current='all';const draw=()=>{const q=qs('#drive-search').value.toLowerCase();const rows=state.drives.filter(d=>(current==='all'||d.status===current)&&`${d.company_name} ${d.role_title}`.toLowerCase().includes(q)).map(d=>`<a href="#/drives/${attr(d.id)}" class="surface drive-row"><div class="company-monogram">${esc(initials(d.company_name))}</div><div class="drive-main"><div class="drive-title"><h3>${esc(d.company_name)}</h3>${statusPill(d.status)}</div><p>${esc(d.role_title)} · ${esc(packageLabel(d))} · ${esc(d.location||'Location not set')}</p><div class="meta-row"><span>Window <b>${esc(statusLabel(windowState(d)))}</b></span><span>Eligible <b>${d.latest_snapshot_eligible_count??'—'}</b></span><span>Assigned <b>${d.assignment_count||0}</b></span><span>Drive <b>${fmtDate(d.drive_date)}</b></span></div></div><span class="drive-arrow">→</span></a>`).join('');qs('#drive-results').innerHTML=rows?`<div class="drive-list">${rows}</div>`:empty('No drives match this view','Adjust the filter or create a new placement drive.')};draw();qs('#drive-search').addEventListener('input',draw);qsa('#drive-filter button').forEach(b=>b.addEventListener('click',()=>{qsa('#drive-filter button').forEach(x=>x.classList.remove('active'));b.classList.add('active');current=b.dataset.value;draw()}));qs('#create-drive').addEventListener('click',openCreateDrive)}

  function checkboxList(name,arr,valKey='code',labelKey='display_name',selected){const sel=selected?new Set(selected):null;return `<div class="checkbox-list" data-checkbox-list="${attr(name)}">${(arr||[]).map(x=>{const val=x[valKey],checked=!!(sel&&sel.has(val));return `<label class="${checked?'checked':''}"><input type="checkbox" name="${attr(name)}" value="${attr(val)}" ${checked?'checked':''}/>${esc(x[labelKey]||val)}</label>`}).join('')}</div>`}
  function bindCheckboxLists(){qsa('[data-checkbox-list]').forEach(box=>box.querySelectorAll('input[type=checkbox]').forEach(cb=>cb.addEventListener('change',()=>cb.closest('label').classList.toggle('checked',cb.checked))))}
  function checkedValues(formEl,name){return [...formEl.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value)}
  function yearOptions(selected){const sel=selected?new Set(selected.map(Number)):null;const now=new Date().getFullYear();const years=[];for(let y=now-1;y<=now+5;y++)years.push(y);return years.map(y=>`<option value="${y}" ${sel&&sel.has(y)?'selected':''}>${y}</option>`).join('')}
  function optionList(arr,valKey='code',labelKey='display_name',selected){const sel=selected?new Set(selected):null;return (arr||[]).map(x=>`<option value="${attr(x[valKey])}" ${sel&&sel.has(x[valKey])?'selected':''}>${esc(x[labelKey]||x[valKey])}</option>`).join('')}
  // Shared by openCreateDrive and drawDriveSetup: the checkbox+reorder+
  // persona-dropdown block for picking a drive's Interview Agents panel.
  // `container` is the element the block's HTML gets inserted into;
  // `getSelection()` returns the current ordered [{track,agent_id}] array,
  // read at submit time by whichever form embeds this block.
  function buildAgentSelectionBlock(container,agentsData,initialSelection){
    const allTracks=['hr','domain','industry','manager'];
    const labels={hr:'HR Interview',domain:'Domain Interview',industry:'Practical Interview',manager:'Managerial Interview'};
    const personasByTrack=track=>(agentsData.agents||[]).filter(a=>a.track===track);
    const selection=initialSelection&&initialSelection.length?initialSelection:allTracks.map(t=>({track:t,agent_id:null}));
    let trackOrder=selection.map(x=>x.track);
    for(const track of allTracks)if(!trackOrder.includes(track))trackOrder.push(track);
    const selectedTracks=new Set(selection.map(x=>x.track));
    const agentChoice={};
    for(const track of allTracks)agentChoice[track]=null;
    for(const item of selection)agentChoice[item.track]=item.agent_id||null;
    const block=document.createElement('div');
    block.className='track-order-block';
    block.innerHTML=`<div class="section-title"><div><h3>Interview panel</h3><p>Choose the engine lanes this drive needs, then assign either a protected default or an independent custom agent. A custom agent keeps its own system prompt.</p></div><a class="section-link" href="#/agents">Create or manage agents →</a></div><span id="track-order-count" class="context-label"></span><div id="track-order-list" class="track-order-list"></div><div id="track-order-error" class="form-error hidden"></div>`;
    container.appendChild(block);
    const drawTracks=()=>{
      qs('#track-order-count').textContent=`${selectedTracks.size} of ${allTracks.length} rounds selected`;
      qs('#track-order-list').innerHTML=trackOrder.map((track,index)=>{
        const personas=personasByTrack(track);
        const options=`<option value="">Default (${esc(labels[track])})</option>${personas.map(p=>`<option value="${attr(p.id)}" ${agentChoice[track]===p.id?'selected':''}>Custom · ${esc(p.name)} — ${esc(p.role)}</option>`).join('')}`;
        const included=selectedTracks.has(track);
        return `<div class="track-order-row"><label><input type="checkbox" data-track="${track}" ${included?'checked':''}/><span class="track-position">${included?[...trackOrder].filter((x,i)=>i<=index&&selectedTracks.has(x)).length:'—'}</span><strong>${esc(labels[track])}</strong></label><select class="field-select track-persona" data-track="${track}" ${included?'':'disabled'}>${options}</select><div class="row-actions"><button type="button" class="row-action track-up" data-track="${track}" ${index===0?'disabled':''}>↑</button><button type="button" class="row-action track-down" data-track="${track}" ${index===trackOrder.length-1?'disabled':''}>↓</button></div></div>`;
      }).join('');
      qsa('#track-order-list input[type=checkbox]').forEach(input=>input.onchange=()=>{input.checked?selectedTracks.add(input.dataset.track):selectedTracks.delete(input.dataset.track);drawTracks()});
      qsa('.track-persona').forEach(sel=>sel.onchange=()=>{agentChoice[sel.dataset.track]=sel.value||null});
      qsa('.track-up,.track-down').forEach(button=>button.onclick=()=>{const from=trackOrder.indexOf(button.dataset.track),to=from+(button.classList.contains('track-up')?-1:1);if(to<0||to>=trackOrder.length)return;[trackOrder[from],trackOrder[to]]=[trackOrder[to],trackOrder[from]];drawTracks()});
    };
    drawTracks();
    return {
      getSelection:()=>trackOrder.filter(track=>selectedTracks.has(track)).map(track=>({track,agent_id:agentChoice[track]||null})),
      validate:()=>{
        if(selectedTracks.size)return true;
        const msg=qs('#track-order-error');msg.textContent='Select at least one interview round.';msg.classList.remove('hidden');return false;
      },
    };
  }

  async function openCreateDrive(){
    const programs=state.catalog||[];const deptMap=new Map();for(const p of programs)for(const d of p.departments||[])if(!deptMap.has(d.code))deptMap.set(d.code,d);const departments=[...deptMap.values()];
    let agentsData={agents:[]};
    try{agentsData=await api('/api/college/agents')}catch(e){/* creation still usable with every round defaulted */}
    overlay.innerHTML=`<div class="modal-layer"><form id="drive-form" class="modal-card modal-card--wide"><div class="modal-heading"><div><span class="context-label">New placement drive</span><h2>Create a hiring workflow</h2><p>Company, role, interview, eligibility, and JD are submitted to the real drive creation API.</p></div><button id="modal-close" type="button" class="icon-button">×</button></div><div class="form-grid two">${field('Company','<input name="company_name" required class="field-input"/>')}${field('Role','<input name="role_title" required class="field-input"/>')}${field('Job type','<select name="job_type" class="field-select"><option value="full_time">Full time</option><option value="internship">Internship</option><option value="internship_plus_ppo">Internship + PPO</option></select>')}${field('Location','<input name="location" class="field-input"/>')}${field('Package (LPA)','<div style="display:flex;gap:8px"><input name="package_min_lpa" class="field-input" type="number" min="0" step="0.1" placeholder="Min"/><input name="package_max_lpa" class="field-input" type="number" min="0" step="0.1" placeholder="Max"/><select name="package_currency" class="field-select" style="max-width:96px">'+['INR','USD','EUR','GBP'].map(c=>`<option value="${c}" ${c==='INR'?'selected':''}>${c}</option>`).join('')+'</select></div>')}${field('Interview duration','<select name="interview_duration_minutes" class="field-select"><option>15</option><option selected>30</option><option>45</option></select>')}${field('Max attempts per candidate','<input name="max_attempts" type="number" min="1" step="1" class="field-input" value="1"/>')}${field('Drive date','<input name="drive_date" type="date" class="field-input"/>')}${field('Application deadline','<input name="application_deadline" type="date" class="field-input"/>')}${field('Interview window starts','<input name="window_start" type="datetime-local" class="field-input"/>')}${field('Interview window ends','<input name="window_end" type="datetime-local" class="field-input"/>')}${field('Minimum CGPA','<input name="min_cgpa" type="number" min="0" max="10" step=".01" class="field-input"/>')}${field('Eligible departments',checkboxList('eligible_departments',departments),'Leave unselected to allow all departments.')}${field('Eligible programs',`<select name="eligible_programs" multiple class="field-select multi">${optionList(programs)}</select>`,'Leave unselected to allow all configured programs.')}${field('Eligible graduation years',`<select name="eligible_graduation_years" multiple class="field-select multi">${yearOptions()}</select>`,'Restrict to specific graduating batches, e.g. this year\'s batch only. Leave unselected to allow every batch.')}</div><div id="agent-selection-host"></div>${field('Job description','<textarea name="jd_text" required class="field-textarea tall" placeholder="Paste the complete job description…"></textarea>')}<div id="drive-form-error" class="form-error hidden"></div><div class="modal-actions"><button id="drive-cancel" type="button" class="button button--secondary">Cancel</button><button id="drive-save" class="button button--primary">Create drive</button></div></form></div>`;
    bindCheckboxLists();
    const agentPanel=buildAgentSelectionBlock(qs('#agent-selection-host'),agentsData,null);
    const close=()=>overlay.innerHTML='';qs('#modal-close').onclick=close;qs('#drive-cancel').onclick=close;
    qs('#drive-form').onsubmit=async e=>{
      e.preventDefault();
      if(!agentPanel.validate())return;
      const f=new FormData(e.currentTarget),programSel=e.currentTarget.elements.eligible_programs,yearSel=e.currentTarget.elements.eligible_graduation_years;
      const body={company_name:f.get('company_name').trim(),role_title:f.get('role_title').trim(),job_type:f.get('job_type'),location:f.get('location').trim()||undefined,package_min_lpa:f.get('package_min_lpa')?Number(f.get('package_min_lpa')):undefined,package_max_lpa:f.get('package_max_lpa')?Number(f.get('package_max_lpa')):undefined,package_currency:f.get('package_currency')||undefined,interview_duration_minutes:Number(f.get('interview_duration_minutes')),max_attempts:f.get('max_attempts')?Number(f.get('max_attempts')):undefined,drive_date:isoDateToDDMMYYYY(f.get('drive_date')),application_deadline:isoDateToDDMMYYYY(f.get('application_deadline')),window_start:localDateTimeToDDMMYYYYAMPM(f.get('window_start')),window_end:localDateTimeToDDMMYYYYAMPM(f.get('window_end')),min_cgpa:f.get('min_cgpa')?Number(f.get('min_cgpa')):undefined,eligible_departments:checkedValues(e.currentTarget,'eligible_departments'),eligible_programs:[...programSel.selectedOptions].map(x=>x.value),eligible_graduation_years:[...yearSel.selectedOptions].map(x=>Number(x.value)),jd_text:f.get('jd_text').trim(),agent_selection:agentPanel.getSelection()};
      const btn=qs('#drive-save'),err=qs('#drive-form-error');btn.disabled=true;btn.textContent='Creating…';
      try{const r=await api('/api/college/drives',{method:'POST',body});close();state.drives=[];toast(r.warnings?.length?`Drive created with ${r.warnings.length} warning(s).`:'Drive created.');go(`/drives/${r.drive_id}`)}
      catch(x){err.textContent=x.message;err.classList.remove('hidden')}
      finally{btn.disabled=false;btn.textContent='Create drive'}
    };
  }
  async function renderDrive(id,params){await loadFoundation();let drive;try{drive=await api(`/api/college/drives/${id}`)}catch(e){app.innerHTML=shell({title:'Placement drive',body:empty('Drive unavailable',e.message||'The drive could not be found.','<a class="button button--secondary" href="#/drives">← Placement drives</a>')});bindShell();return}const allowed=['overview','candidates','eligibility','ats','results','skills','departments','setup'];const tab=allowed.includes(params.get('tab'))?params.get('tab'):'overview';const tabs=allowed.map(x=>`<button data-tab="${x}" class="${x===tab?'active':''}">${({overview:'Overview',candidates:'Candidates',eligibility:'Eligibility',ats:'ATS Fit',results:'Interview Results',skills:'Skill Intelligence',departments:'Departments',setup:'Drive Setup'})[x]}</button>`).join('');app.innerHTML=shell({body:`<a class="back-link admin-back" href="#/drives">← All placement drives</a><div class="drive-hero"><div class="company-monogram large">${esc(initials(drive.company_name))}</div><div class="drive-hero-main"><div><span class="eyebrow">Placement drive</span><h1>${esc(drive.company_name)}</h1><p>${esc(drive.role_title)} · ${esc(packageLabel(drive))} · ${esc(drive.location||'Location not set')}</p></div><div class="drive-badges">${statusPill(drive.status)}${statusPill('Window '+statusLabel(windowState(drive)),windowState(drive)==='open'?'brand':'neutral')}${drive.is_locked?statusPill('Access locked','amber'):''}<button id="drive-lock-toggle" class="button button--secondary button--small" type="button">${drive.is_locked?'Unlock access':'Lock access'}</button></div></div></div><nav class="workspace-tabs">${tabs}</nav><div id="drive-tab"></div>`});bindShell();qsa('.workspace-tabs button').forEach(b=>b.onclick=()=>go(`/drives/${id}?tab=${b.dataset.tab}`));qs('#drive-lock-toggle').onclick=async()=>{const btn=qs('#drive-lock-toggle'),next=!drive.is_locked;if(!confirm(next?'Lock interview access for this drive? Students will be unable to start or resume interviews until you unlock it.':'Unlock interview access for this drive?'))return;btn.disabled=true;try{await api(`/api/college/drives/${id}/lock`,{method:'POST',body:{is_locked:next}});toast(next?'Drive access locked.':'Drive access unlocked.');renderDrive(id,params)}catch(x){toast(x.message,'error');btn.disabled=false}};await renderDriveTab(id,drive,tab)}
  async function renderDriveTab(id,drive,tab){const root=qs('#drive-tab');root.innerHTML='<div class="skeleton"></div>';try{if(tab==='overview')return drawDriveOverview(root,drive,await api(`/api/college/drives/${id}/dashboard/overview`));if(tab==='candidates')return drawCandidates(root,id,await fetchAllRanking(id));if(tab==='eligibility'){const [s,c]=await Promise.all([api(`/api/college/drives/${id}/eligibility`),fetchAllEligibilityCandidates(id)]);return drawEligibility(root,id,s,c)}if(tab==='ats')return drawAtsFit(root,id);if(tab==='results')return drawResults(root,id,await fetchAllRanking(id));if(tab==='skills')return drawSkills(root,await api(`/api/college/drives/${id}/dashboard/skill-gap`));if(tab==='departments')return drawDepartments(root,await api(`/api/college/drives/${id}/dashboard/departments`));if(tab==='setup')return await drawDriveSetup(root,drive)}catch(e){root.innerHTML=`<div class="form-error">${esc(e.message||'Could not load this section.')}</div>`}}
  function drawDriveOverview(root,drive,d){const r=d.metrics.readiness_distribution;root.innerHTML=`<div class="workspace-grid"><div><section class="metric-grid three">${metric('Assigned',d.metrics.total_assigned,'Candidate assignments')}${metric('Evaluated',d.metrics.interview_completed,'Stage 6 outcomes')}${metric('Avg. interview score',d.metrics.average_readiness_score==null?'—':score(d.metrics.average_readiness_score),'Released evidence only')}</section><section class="surface panel">${sectionTitle('Candidate readiness','Readiness categories from completed Stage 6 evaluations.')}<div class="readiness-grid">${[['Interview Ready',r.interview_ready],['Approaching Ready',r.approaching_ready],['Developing',r.developing],['Not Ready',r.not_ready]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('')}</div></section></div><aside><section class="surface panel">${sectionTitle('Operational status','Independent lifecycle signals.')}<dl class="detail-list">${detailRow('Business lifecycle',drive.status)}${detailRow('Interview window',windowState(drive))}${detailRow('Interview access',drive.is_locked?'Locked':'Enabled')}${detailRow('JD',drive.jd_document_id?(drive.jd_parse_status||'Configured'):'Missing')}</dl></section><section class="surface panel">${sectionTitle('Schedule')}<dl class="detail-list">${detailRow('Application deadline',fmtDate(drive.application_deadline))}${detailRow('Drive date',fmtDate(drive.drive_date))}${detailRow('Window opens',fmtDateTime(drive.window_start_at))}${detailRow('Window closes',fmtDateTime(drive.window_end_at))}${detailRow('Interview duration',`${drive.interview_duration_minutes} min`)}</dl></section></aside></div>`}
  function detailRow(label,value){return `<div><dt>${esc(label)}</dt><dd>${esc(statusLabel(value))}</dd></div>`}
  async function fetchAllRanking(id){const PAGE=500;let offset=0,data=await api(`/api/college/drives/${id}/dashboard/ranking?limit=${PAGE}&offset=0`);const total=data.pagination?.total??data.candidates.length;while(data.candidates.length<total){offset+=PAGE;const next=await api(`/api/college/drives/${id}/dashboard/ranking?limit=${PAGE}&offset=${offset}`);if(!next.candidates.length)break;data.candidates=data.candidates.concat(next.candidates)}return data}
  async function fetchAllEligibilityCandidates(id){const PAGE=200;let offset=0,data=await api(`/api/college/drives/${id}/eligibility/candidates?limit=${PAGE}&offset=0`);while(data.candidates.length===offset+PAGE){offset+=PAGE;const next=await api(`/api/college/drives/${id}/eligibility/candidates?limit=${PAGE}&offset=${offset}`);data.candidates=data.candidates.concat(next.candidates);if(next.candidates.length<PAGE)break}return data}
  function candidateRows(id,rows,selected){return rows.map(c=>`<tr><td><input type="checkbox" class="candidate-select" data-student="${attr(c.student_id)}" ${selected.has(c.student_id)?'checked':''}/></td><td><strong>${c.rank?`#${c.rank}`:'—'}</strong></td><td><strong>${esc(c.full_name)}</strong><span>${esc(c.roll_number)} · ${esc(c.department_code)}</span></td><td><div class="score-cell"><strong>${score(c.ranking_score)}</strong>${!c.decision_support?.comparable?'<span>Review required</span>':''}</div></td><td><strong>${score(c.overall_score)}</strong></td><td>${statusPill(c.readiness||'Not assessed')}</td><td><span class="recommendation-cell">${esc(c.recommendation)}</span></td><td><span class="decision-pill" data-student="${attr(c.student_id)}">${statusPill(c.officer_decision||'Undecided')}</span></td><td><span class="publication-pill" data-student="${attr(c.student_id)}">${statusPill(c.publication?.state||'hidden')}</span></td><td><button class="row-action candidate-open" data-student="${attr(c.student_id)}" data-assignment="${attr(c.assignment_id)}">Review →</button></td></tr>`).join('')}

  function drawCandidates(root,id,data){
    const all=data.candidates;
    const selected=new Set();
    const recommendationOptions=[...new Set(all.map(c=>c.recommendation).filter(Boolean))].sort();
    const filters={q:'',minScore:'',maxScore:'',readiness:'',recommendation:'',decision:'',publication:''};

    const applyFilters=()=>all.filter(c=>{
      const q=filters.q;
      if(q && !`${c.full_name} ${c.roll_number} ${c.department_code}`.toLowerCase().includes(q))return false;
      if(filters.minScore!=='' && !(c.overall_score!=null && c.overall_score>=Number(filters.minScore)))return false;
      if(filters.maxScore!=='' && !(c.overall_score!=null && c.overall_score<=Number(filters.maxScore)))return false;
      if(filters.readiness && c.readiness!==filters.readiness)return false;
      if(filters.recommendation && c.recommendation!==filters.recommendation)return false;
      if(filters.decision){const d=c.officer_decision||'undecided';if(d!==filters.decision)return false}
      if(filters.publication && (c.publication?.state||'hidden')!==filters.publication)return false;
      return true;
    });

    root.innerHTML=`<div class="toolbar surface"><div class="search-field">⌕<input id="candidate-search" placeholder="Search candidate, roll number, department…"/></div><span class="toolbar-note" id="candidate-count">${data.pagination?.total??all.length} assigned</span></div>
    <div class="toolbar surface" style="flex-wrap:wrap">
      <input id="filter-min-score" class="field-input" style="max-width:110px" type="number" min="0" max="100" placeholder="Min score"/>
      <input id="filter-max-score" class="field-input" style="max-width:110px" type="number" min="0" max="100" placeholder="Max score"/>
      <select id="filter-readiness" class="toolbar-select"><option value="">All readiness</option>${['Interview Ready','Approaching Ready','Developing','Not Ready'].map(r=>`<option value="${attr(r)}">${esc(r)}</option>`).join('')}</select>
      <select id="filter-recommendation" class="toolbar-select"><option value="">All AI recommendations</option>${recommendationOptions.map(r=>`<option value="${attr(r)}">${esc(r)}</option>`).join('')}</select>
      <select id="filter-decision" class="toolbar-select"><option value="">All college decisions</option><option value="undecided">Not decided</option><option value="shortlist">Shortlist</option><option value="hold">Hold</option><option value="reject">Reject</option></select>
      <select id="filter-publication" class="toolbar-select"><option value="">All publication states</option><option value="hidden">Hidden</option><option value="scheduled">Scheduled</option><option value="released">Released</option></select>
      <button id="filter-clear" class="button button--secondary">Clear filters</button>
    </div>
    <div id="bulk-bar" class="toolbar surface hidden" style="background:var(--brand-softer)">
      <span class="toolbar-note" id="bulk-count" style="margin-left:0"></span>
      <button type="button" data-decision="shortlist" class="button button--secondary bulk-decision">Shortlist selected</button>
      <button type="button" data-decision="hold" class="button button--secondary bulk-decision">Hold selected</button>
      <button type="button" data-decision="reject" class="button button--secondary bulk-decision">Reject selected</button>
      <button type="button" id="bulk-release" class="button button--primary">Release results for selected</button>
      <button type="button" id="bulk-reopen" class="button button--secondary">Reopen selected for another attempt</button>
    </div>
    <div class="surface table-shell"><table class="data-table candidate-table"><thead><tr><th><input type="checkbox" id="select-all"/></th><th>Rank</th><th>Candidate</th><th>PRI</th><th>Interview</th><th>Readiness</th><th>AI recommendation</th><th>College decision</th><th>Publication</th><th></th></tr></thead><tbody id="candidate-body">${candidateRows(id,all,selected)}</tbody></table><div id="candidate-empty" class="empty-table hidden">No candidates match this filter.</div></div>`;

    let visible=all;

    const updateBulkBar=()=>{
      const bar=qs('#bulk-bar');
      bar.classList.toggle('hidden',selected.size===0);
      qs('#bulk-count').textContent=`${selected.size} selected`;
      const selectAll=qs('#select-all');
      if(selectAll){selectAll.checked=visible.length>0 && visible.every(c=>selected.has(c.student_id));}
    };

    const bind=()=>{
      qsa('.candidate-open').forEach(b=>b.onclick=()=>openCandidate(id,all.find(c=>c.student_id===b.dataset.student)));
      qsa('.candidate-select').forEach(cb=>cb.onchange=()=>{
        if(cb.checked)selected.add(cb.dataset.student);else selected.delete(cb.dataset.student);
        updateBulkBar();
      });
      updateBulkBar();
    };
    bind();

    const redraw=()=>{
      visible=applyFilters();
      qs('#candidate-body').innerHTML=candidateRows(id,visible,selected);
      qs('#candidate-empty').classList.toggle('hidden',visible.length>0);
      qs('#candidate-count').textContent=`${visible.length} of ${all.length} assigned`;
      bind();
    };

    qs('#candidate-search').oninput=e=>{filters.q=e.target.value.toLowerCase();redraw()};
    qs('#filter-min-score').oninput=e=>{filters.minScore=e.target.value;redraw()};
    qs('#filter-max-score').oninput=e=>{filters.maxScore=e.target.value;redraw()};
    qs('#filter-readiness').onchange=e=>{filters.readiness=e.target.value;redraw()};
    qs('#filter-recommendation').onchange=e=>{filters.recommendation=e.target.value;redraw()};
    qs('#filter-decision').onchange=e=>{filters.decision=e.target.value;redraw()};
    qs('#filter-publication').onchange=e=>{filters.publication=e.target.value;redraw()};
    qs('#filter-clear').onclick=()=>{
      filters.q=filters.minScore=filters.maxScore=filters.readiness=filters.recommendation=filters.decision=filters.publication='';
      qs('#candidate-search').value='';qs('#filter-min-score').value='';qs('#filter-max-score').value='';
      qs('#filter-readiness').value='';qs('#filter-recommendation').value='';qs('#filter-decision').value='';qs('#filter-publication').value='';
      redraw();
    };
    qs('#select-all').onchange=e=>{
      if(e.target.checked)visible.forEach(c=>selected.add(c.student_id));
      else visible.forEach(c=>selected.delete(c.student_id));
      redraw();
    };

    qsa('.bulk-decision').forEach(b=>b.onclick=async()=>{
      const decision=b.dataset.decision;
      const ids=[...selected];
      if(!ids.length)return;
      if(!confirm(`${statusLabel(decision)} ${ids.length} selected candidate(s)?`))return;
      b.disabled=true;
      try{
        const r=await api(`/api/college/drives/${id}/candidates/decisions/bulk`,{method:'PUT',body:{student_ids:ids,decision}});
        r.updated.forEach(u=>{const c=all.find(x=>x.student_id===u.student_id);if(c){c.officer_decision=decision}});
        toast(`${r.updated.length} candidate(s) ${decision==='hold'?'held':decision+'ed'}.${r.skipped.length?` ${r.skipped.length} skipped.`:''}`);
        redraw();
      }catch(x){toast(x.message,'error')}finally{b.disabled=false}
    });
    qs('#bulk-release').onclick=async()=>{
      const ids=[...selected];
      if(!ids.length)return;
      if(!confirm(`Release results to ${ids.length} selected candidate(s) now? Only candidates whose evaluation has actually finished will be released.`))return;
      const btn=qs('#bulk-release');btn.disabled=true;
      try{
        const r=await api(`/api/college/drives/${id}/candidates/release-bulk`,{method:'PUT',body:{student_ids:ids}});
        r.updated.forEach(u=>{const c=all.find(x=>x.student_id===u.student_id);if(c){c.publication={...(c.publication||{}),state:'released'}}});
        toast(`${r.updated.length} result(s) released.${r.skipped.length?` ${r.skipped.length} not ready.`:''}`);
        redraw();
      }catch(x){toast(x.message,'error')}finally{btn.disabled=false}
    };
    qs('#bulk-reopen').onclick=async()=>{
      const ids=[...selected];
      if(!ids.length)return;
      if(!confirm(`Reopen ${ids.length} selected candidate(s) for another attempt? Only candidates who already completed this drive's interview, and are not already at their attempt cap, will be reopened.`))return;
      const btn=qs('#bulk-reopen');btn.disabled=true;
      try{
        const r=await api(`/api/college/drives/${id}/candidates/reopen-bulk`,{method:'POST',body:{student_ids:ids}});
        toast(`${r.reopened.length} candidate(s) reopened for another attempt.${r.skipped.length?` ${r.skipped.length} skipped.`:''}`);
      }catch(x){toast(x.message,'error')}finally{btn.disabled=false}
    };
  }
  function drawEligibility(root,id,s,c){const rows=c.candidates||[];root.innerHTML=`<div class="metric-grid three">${metric('Eligible',s.snapshot?.eligible_count??'—','Latest snapshot')}${metric('Not eligible',s.snapshot?.not_eligible_count??'—','Latest snapshot')}${metric('Snapshot',s.snapshot?`v${s.snapshot.version}`:'—',s.snapshot?fmtDateTime(s.snapshot.created_at):'Not computed')}</div><div class="toolbar surface"><div class="segmented" id="elig-filter"><button data-f="all" class="active">All</button><button data-f="eligible">Eligible</button><button data-f="not">Not eligible</button></div><button id="recompute" class="button button--secondary">Recompute eligibility</button></div><div class="surface table-shell"><table class="data-table"><thead><tr><th>Candidate</th><th>CGPA</th><th>Resume</th><th>Skill match</th><th>Eligibility</th><th>Why</th></tr></thead><tbody id="elig-body"></tbody></table></div>`;const render=f=>{const list=rows.filter(x=>f==='all'||(f==='eligible'?x.eligible:!x.eligible));qs('#elig-body').innerHTML=list.map(x=>`<tr><td><strong>${esc(x.full_name)}</strong><span>${esc(x.roll_number)} · ${esc(x.department_code)}</span></td><td>${x.cgpa??'—'}</td><td>${x.has_resume?'Available':'—'}</td><td>${x.matched_skills?.length||0} matched${x.missing_skills?.length?` · ${x.missing_skills.length} missing`:''}</td><td>${statusPill(x.eligible?'Eligible':'Not eligible')}</td><td><span class="small-copy">${esc((x.reason_codes||x.reasons||[]).map(statusLabel).join(', ')||'Meets configured criteria')}</span></td></tr>`).join('')};render('all');qsa('#elig-filter button').forEach(b=>b.onclick=()=>{qsa('#elig-filter button').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.f)});qs('#recompute').onclick=async()=>{if(!confirm('Recompute eligibility? This creates a new immutable snapshot and may update assignments.'))return;const btn=qs('#recompute');btn.disabled=true;btn.textContent='Recomputing…';try{await api(`/api/college/drives/${id}/eligibility`,{method:'POST'});toast('Eligibility recomputed.');const ri=routeInfo();renderDrive(id,ri.params)}catch(e){toast(e.message,'error')}finally{btn.disabled=false}}}
  function drawResults(root,id,data){const rows=data.candidates.filter(c=>c.overall_score!=null||c.evaluation_status!=='incomplete');const hiddenReadyCount=rows.filter(c=>(c.publication?.state||'hidden')==='hidden'&&c.evaluation_status==='released').length;root.innerHTML=`<div class="info-banner"><strong>Evaluation readiness ≠ student publication.</strong><span>Review Stage 6 evidence, record a human decision, then release the result separately when appropriate.</span></div><div class="surface panel" style="margin:0 0 14px;padding:16px"><div class="modal-actions left"><button id="release-all-results" class="button button--primary" ${hiddenReadyCount?'':'disabled'}>Release all ready now${hiddenReadyCount?` (${hiddenReadyCount})`:''}</button><div class="schedule-row"><input id="release-all-time" class="field-input" type="datetime-local"/><button id="schedule-all-results" class="button button--secondary" ${hiddenReadyCount?'':'disabled'}>Schedule for everyone</button></div></div><p class="footnote" style="margin:8px 0 0">Only affects candidates whose evaluation has actually finished — never a still-scoring or dropped one. Scheduling sets the same release time for every one of them at once.</p></div><div class="surface table-shell"><table class="data-table"><thead><tr><th>Candidate</th><th>Interview</th><th>PRI</th><th>Evaluation</th><th>AI recommendation</th><th>College decision</th><th>Student visibility</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong><span>${esc(c.roll_number)}</span></td><td><strong>${score(c.overall_score)}</strong></td><td><strong>${score(c.ranking_score)}</strong></td><td>${statusPill(c.evaluation_status)}</td><td>${esc(c.recommendation)}</td><td><span class="decision-pill" data-student="${attr(c.student_id)}">${statusPill(c.officer_decision||'Undecided')}</span></td><td><span class="publication-pill" data-student="${attr(c.student_id)}">${statusPill(c.publication?.state||'hidden')}</span></td><td><button class="row-action result-open" data-student="${attr(c.student_id)}">Open report →</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty-table">No evaluated interviews yet.</div>'}</div>`;qsa('.result-open').forEach(b=>b.onclick=()=>openCandidate(id,rows.find(c=>c.student_id===b.dataset.student)));const releaseAllBtn=qs('#release-all-results');if(releaseAllBtn)releaseAllBtn.onclick=async()=>{if(!confirm(`Release results to all ${hiddenReadyCount} candidate(s) whose evaluation is already finished? Candidates still being scored are never affected.`))return;releaseAllBtn.disabled=true;releaseAllBtn.textContent='Releasing…';try{const r=await api(`/api/college/drives/${id}/candidates/release-all`,{method:'PUT'});toast(r.released_count?`Released ${r.released_count} result(s).${r.not_ready_count?` ${r.not_ready_count} still not ready.`:''}`:'Nothing was ready to release.');renderDrive(id,routeInfo().params)}catch(x){toast(x.message,'error');releaseAllBtn.disabled=false;releaseAllBtn.textContent=`Release all ready now (${hiddenReadyCount})`}};const scheduleAllBtn=qs('#schedule-all-results');if(scheduleAllBtn)scheduleAllBtn.onclick=async()=>{const v=qs('#release-all-time').value;if(!v){toast('Choose a future release date and time.','error');return}if(!confirm(`Schedule all ${hiddenReadyCount} ready result(s) to release at ${new Date(v).toLocaleString()}? Candidates still being scored are never affected.`))return;scheduleAllBtn.disabled=true;scheduleAllBtn.textContent='Scheduling…';try{const r=await api(`/api/college/drives/${id}/candidates/release-all/schedule`,{method:'PUT',body:{scheduled_for:new Date(v).toISOString()}});toast(r.scheduled_count?`Scheduled ${r.scheduled_count} result(s).${r.not_ready_count?` ${r.not_ready_count} still not ready.`:''}`:'Nothing was ready to schedule.');renderDrive(id,routeInfo().params)}catch(x){toast(x.message,'error');scheduleAllBtn.disabled=false;scheduleAllBtn.textContent='Schedule for everyone'}}}
  // Skill Intelligence V1 / Skill Risk Radar (CLAUDE.md SKL-001). `d` is
  // `dashboard_service.get_skill_intelligence`'s response — replaces the
  // older flat gap-list shape this function used to render (kept alive,
  // unused, as `get_skill_gap_intelligence` for its own tests).
  const _riskTone={high:'red',medium:'amber',low:'green',insufficient_data:'neutral'};
  const _riskLabel={high:'High risk',medium:'Medium risk',low:'Low risk',insufficient_data:'Insufficient data'};
  function drawSkills(root,d){
    if(!d.skills?.length){root.innerHTML=empty('No JD skills to assess yet','Skill intelligence appears once this drive has a parsed JD and at least one released Stage 6 evaluation.');return}
    const byPriority={mandatory:[],core:[],preferred:[]};
    d.skills.forEach(s=>{(byPriority[s.priority]||(byPriority[s.priority]=[])).push(s)});
    const priorityOrder=['mandatory','core','preferred',...Object.keys(byPriority).filter(p=>!['mandatory','core','preferred'].includes(p))];
    const skillRow=s=>`<tr><td><strong>${esc(s.skill)}</strong></td><td>${s.coverage_pct}%<span class="small-copy">${s.assessed_count} of ${s.total_candidates} assessed</span></td><td>${s.risk==='insufficient_data'?'—':`${s.gap_pct}%`}</td><td>${statusPill(_riskLabel[s.risk]||s.risk,_riskTone[s.risk])}</td></tr>`;
    const prioritySection=p=>{const rows=byPriority[p];if(!rows?.length)return'';return `<div class="gap-list"><h4 class="context-label">${esc(statusLabel(p))} skills</h4><div class="surface table-shell"><table class="data-table"><thead><tr><th>Skill</th><th>Coverage</th><th>Gap</th><th>Risk</th></tr></thead><tbody>${rows.map(skillRow).join('')}</tbody></table></div></div>`};
    const topRisks=d.top_risks||[];
    const insufficientData=d.insufficient_data_skills||[];
    const historical=d.unmatched_historical_skills||[];
    root.innerHTML=`<div class="workspace-grid"><section class="surface panel">${sectionTitle('Top skill risks','Adequately assessed skills only, ranked by risk to this job — priority beats raw gap size.',`<span class="toolbar-note">${d.total_released} released evaluation(s)</span>`)}${topRisks.length?`<div class="surface table-shell"><table class="data-table"><thead><tr><th>Rank</th><th>Skill</th><th>Priority</th><th>Gap</th><th>Coverage</th><th>Risk</th></tr></thead><tbody>${topRisks.map(r=>`<tr><td>#${r.rank}</td><td><strong>${esc(r.skill)}</strong></td><td>${esc(statusLabel(r.priority))}</td><td>${r.gap_pct}%</td><td>${r.coverage_pct}%</td><td>${statusPill(_riskLabel[r.risk]||r.risk,_riskTone[r.risk])}</td></tr>`).join('')}</tbody></table></div>`:empty('No high or medium risk skills','Every adequately-assessed skill in this drive is currently low risk.')}
    ${priorityOrder.map(prioritySection).join('')}
    </section><aside>
    <section class="surface panel">${sectionTitle('JD requirements','Every skill this drive\'s JD asks for, by priority — the same list Risk Radar ranks against.')}${priorityOrder.filter(p=>byPriority[p]?.length).map(p=>`<div class="gap-list"><h4 class="context-label">${esc(statusLabel(p))}</h4><div style="display:flex;flex-wrap:wrap;gap:6px">${byPriority[p].map(s=>`<span class="status-pill neutral">${esc(s.skill)}</span>`).join('')}</div></div>`).join('')}</section>
    <section class="surface panel">${sectionTitle('Insufficient data','Not assessed broadly enough across the cohort for a reliable conclusion — never treated as weak.')}${insufficientData.length?`<div class="intervention-list">${insufficientData.map(s=>`<article><strong>${esc(s.skill)}</strong><p>${esc(statusLabel(s.priority))} · ${s.coverage_pct}% coverage (${s.assessed_count} of ${s.total_count})</p><small>Not assessed broadly enough to make a reliable cohort conclusion.</small></article>`).join('')}</div>`:'<p class="footnote">Every skill has adequate cohort coverage.</p>'}</section>
    ${historical.length?`<section class="surface panel">${sectionTitle('Historical / unmatched skills','Appeared in a past version of this JD but not the current one — kept for audit, never assigned a priority or ranked.')}<div class="intervention-list">${historical.map(s=>`<article><strong>${esc(s.skill)}</strong><p>Priority unknown · ${s.coverage_pct}% coverage (${s.assessed_count} of ${s.total_candidates})</p></article>`).join('')}</div></section>`:''}
    </aside></div>`;
  }

  // ATS Resume Fit V1 (CLAUDE.md ATS-001) — pre-interview resume-vs-JD
  // screening. Filters are server-side query params (the score is computed
  // fresh per call, not a stored column), so each filter change re-fetches
  // rather than filtering an already-loaded list client-side.
  async function drawAtsFit(root,id){
    root.innerHTML='<div class="skeleton"></div>';
    const filters={eligibleOnly:false,minFit:'',minMandatory:''};
    const load=async()=>{
      const params=new URLSearchParams({limit:'500'});
      if(filters.eligibleOnly)params.set('eligible_only','true');
      if(filters.minFit!=='')params.set('min_ats_fit',filters.minFit);
      if(filters.minMandatory!=='')params.set('min_mandatory_coverage_pct',filters.minMandatory);
      const data=await api(`/api/college/drives/${id}/dashboard/ats-fit?${params.toString()}`);
      render(data);
    };
    const render=(data)=>{
      root.innerHTML=`<div class="info-banner"><strong>ATS Fit measures resume alignment, not competency.</strong><span>It only orders who gets reviewed first — the interview is what verifies real skill.</span></div>
      <div class="toolbar surface" style="flex-wrap:wrap">
        <label style="display:flex;align-items:center;gap:6px"><input type="checkbox" id="ats-eligible-only" ${filters.eligibleOnly?'checked':''}/> Eligible only</label>
        <input id="ats-min-fit" class="field-input" style="max-width:150px" type="number" min="0" max="100" placeholder="Min ATS fit %" value="${attr(filters.minFit)}"/>
        <input id="ats-min-mandatory" class="field-input" style="max-width:190px" type="number" min="0" max="100" placeholder="Min mandatory coverage %" value="${attr(filters.minMandatory)}"/>
        <button id="ats-apply" class="button button--primary">Apply filters</button>
        <button id="ats-clear" class="button button--secondary">Clear filters</button>
        <span class="toolbar-note">${data.total_count} candidate(s)</span>
      </div>
      <div class="surface table-shell"><table class="data-table"><thead><tr><th>Candidate</th><th>Eligible</th><th>ATS fit</th><th>Mandatory</th><th>Core</th><th>Preferred</th><th>Resume evidence</th></tr></thead><tbody>${data.candidates.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong><span>${esc(c.roll_number)} · ${esc(c.department_code)}</span></td><td>${c.eligible==null?'—':statusPill(c.eligible?'Eligible':'Not eligible')}</td><td><strong>${c.ats_fit_score==null?'—':c.ats_fit_score+'%'}</strong></td><td>${esc(c.mandatory_coverage)}</td><td>${esc(c.core_coverage)}</td><td>${esc(c.preferred_coverage)}</td><td>${statusPill(statusLabel(c.resume_evidence))}</td></tr>`).join('')}</tbody></table>${data.candidates.length?'':'<div class="empty-table">No candidates match this filter.</div>'}</div>`;
      // A live per-keystroke refetch (the pattern the client-side-filtered
      // Candidates/Drives search boxes use) would hit this endpoint's real
      // per-candidate skill-matching computation on every character typed —
      // an explicit Apply is the deliberate choice here, not an oversight.
      qs('#ats-eligible-only').onchange=e=>{filters.eligibleOnly=e.target.checked;load()};
      qs('#ats-min-fit').oninput=e=>{filters.minFit=e.target.value};
      qs('#ats-min-mandatory').oninput=e=>{filters.minMandatory=e.target.value};
      qs('#ats-apply').onclick=()=>load();
      qs('#ats-clear').onclick=()=>{filters.eligibleOnly=false;filters.minFit='';filters.minMandatory='';load()};
    };
    try{await load()}catch(e){root.innerHTML=`<div class="form-error">${esc(e.message||'Could not load ATS Fit.')}</div>`}
  }
  function drawDepartments(root,d){const r=d.recommended_department;root.innerHTML=`<div class="info-banner"><strong>Cohort context only.</strong><span>Department never changes an individual candidate score, PRI, or ranking.</span></div>${r?`<div class="surface panel" style="margin-bottom:14px">${sectionTitle('Recommended department',r.basis,statusPill('Advisory only','amber'))}<div class="metric-grid three" style="margin-top:12px">${metric('Department',r.department_code,`${r.student_count} assessed candidate(s)`)}${metric('Ready rate',`${Math.round(r.interview_ready_rate)}%`,'Interview-ready share')}${metric('Avg. score',score(r.avg_score),'Released evidence only')}</div><p class="footnote" style="margin:10px 0 0">Never used to score, rank, or filter individual candidates — cohort context only, same as the table below.</p></div>`:''}<div class="surface table-shell"><table class="data-table"><thead><tr><th>Department</th><th>Students</th><th>Interview ready</th><th>Need training</th><th>Avg. score</th><th>Ready rate</th></tr></thead><tbody>${(d.departments||[]).map(x=>`<tr><td><strong>${esc(x.department_code)}</strong></td><td>${x.student_count}</td><td>${x.interview_ready_count}</td><td>${x.need_training_count}</td><td>${score(x.avg_score)}</td><td>${Math.round(x.interview_ready_rate)}%</td></tr>`).join('')}</tbody></table></div>${d.analysis_note?`<p class="footnote">${esc(d.analysis_note)}</p>`:''}`}
  function localInput(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v).slice(0,16);const l=new Date(d.getTime()-d.getTimezoneOffset()*60000);return l.toISOString().slice(0,16)}
  // Backend date/window fields are DD-MM-YYYY / "DD-MM-YYYY hh:mm AM/PM" at
  // the API boundary (CLAUDE.md DRV-026) while native <input type=date> /
  // <input type=datetime-local> always produce YYYY-MM-DD / YYYY-MM-DDTHH:MM
  // — these convert the picker's native value to the wire format on submit
  // only; the picker itself is untouched.
  function isoDateToDDMMYYYY(v){if(!v)return undefined;const[y,m,dd]=v.split('-');if(!y||!m||!dd)return undefined;return `${dd}-${m}-${y}`}
  function localDateTimeToDDMMYYYYAMPM(v){if(!v)return undefined;const[datePart,timePart]=v.split('T');if(!datePart||!timePart)return undefined;const[y,m,dd]=datePart.split('-');const[hStr,mStr]=timePart.split(':');let h=Number(hStr);const mm=String(Number(mStr)).padStart(2,'0');const ampm=h>=12?'PM':'AM';h=h%12;if(h===0)h=12;return `${dd}-${m}-${y} ${String(h).padStart(2,'0')}:${mm} ${ampm}`}
  function drawDriveSetupLegacy(root,d){const programs=state.catalog||[];const deptMap=new Map();for(const p of programs)for(const dep of p.departments||[])if(!deptMap.has(dep.code))deptMap.set(dep.code,dep);const departments=[...deptMap.values()];root.innerHTML=`<form id="setup-form" class="setup-layout"><section class="surface panel">${sectionTitle('Drive configuration','Edit the supported backend fields. Operational states remain separate.')}<div id="setup-msg" class="hidden"></div><div class="form-grid two">${field('Company',`<input name="company_name" required class="field-input" value="${attr(d.company_name)}"/>`)}${field('Role',`<input name="role_title" required class="field-input" value="${attr(d.role_title)}"/>`)}${field('Job type',`<select name="job_type" class="field-select"><option value="full_time" ${d.job_type==='full_time'?'selected':''}>Full time</option><option value="internship" ${d.job_type==='internship'?'selected':''}>Internship</option><option value="internship_plus_ppo" ${d.job_type==='internship_plus_ppo'?'selected':''}>Internship + PPO</option></select>`)}${field('Location',`<input name="location" class="field-input" value="${attr(d.location||'')}"/>`)}${field('Package (LPA)',`<div style="display:flex;gap:8px"><input name="package_min_lpa" class="field-input" type="number" min="0" step="0.1" placeholder="Min" value="${attr(d.package_min_lpa??'')}"/><input name="package_max_lpa" class="field-input" type="number" min="0" step="0.1" placeholder="Max" value="${attr(d.package_max_lpa??'')}"/><select name="package_currency" class="field-select" style="max-width:96px">${['INR','USD','EUR','GBP'].map(c=>`<option value="${c}" ${(d.package_currency||'INR')===c?'selected':''}>${c}</option>`).join('')}</select></div>`)}${field('Minimum CGPA',`<input name="min_cgpa" class="field-input" type="number" min="0" max="10" step=".01" value="${attr(d.criteria_min_cgpa??'')}"/>`)}${field('Max attempts per candidate',`<input name="max_attempts" class="field-input" type="number" min="1" step="1" value="${attr(d.max_attempts??1)}"/>`,'How many times a student may attempt this drive\'s interview by default.')}${field('Drive date',`<input name="drive_date" class="field-input" type="date" value="${attr((d.drive_date||'').slice(0,10))}"/>`)}${field('Application deadline',`<input name="application_deadline" class="field-input" type="date" value="${attr((d.application_deadline||'').slice(0,10))}"/>`)}${field('Window starts',`<input name="window_start" class="field-input" type="datetime-local" value="${attr(localInput(d.window_start_at||d.window_start))}"/>`)}${field('Window ends',`<input name="window_end" class="field-input" type="datetime-local" value="${attr(localInput(d.window_end_at||d.window_end))}"/>`)}${field('Interview duration',`<select name="interview_duration_minutes" class="field-select">${[15,30,45].map(x=>`<option value="${x}" ${d.interview_duration_minutes===x?'selected':''}>${x} minutes</option>`).join('')}</select>`)}${field('Business lifecycle',`<select name="status" class="field-select">${['draft','active','closed','cancelled'].map(x=>`<option value="${x}" ${d.status===x?'selected':''}>${statusLabel(x)}</option>`).join('')}</select>`)}${field('Eligible departments',checkboxList('eligible_departments',departments,'code','display_name',d.criteria_department_codes),'Leave unselected to allow all departments.')}${field('Eligible programs',`<select name="eligible_programs" multiple class="field-select multi">${optionList(programs,'code','display_name',d.criteria_programs)}</select>`,'Leave unselected to allow all configured programs.')}${field('Eligible graduation years',`<select name="eligible_graduation_years" multiple class="field-select multi">${yearOptions(d.criteria_graduation_years)}</select>`,'Restrict to specific graduating batches, e.g. this year\'s batch only. Leave unselected to allow every batch.')}</div><div class="modal-actions left"><button id="setup-save" class="button button--primary">Save configuration</button></div></section><aside><section class="surface panel">${sectionTitle('Job description','Replacing this re-parses the JD. Leave blank to keep the current one.',statusPill(d.jd_document_id?(d.jd_parse_status||'Configured'):'Missing'))}<textarea id="setup-jd" class="field-textarea jd-box" placeholder="Paste a replacement JD only when you want to update it…">${esc(d.jd_raw_text||'')}</textarea><p class="footnote">Leaving this unchanged (or blank) preserves the current JD.</p></section><section class="surface panel danger-zone">${sectionTitle('Destructive action','Delete is attempted only when the backend accepts the current drive state.')}<button id="delete-drive" type="button" class="button button--danger">Delete drive</button></section></aside></form>`;bindCheckboxLists();qs('#setup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=qs('#setup-save'),msg=qs('#setup-msg'),programSel=e.currentTarget.elements.eligible_programs,yearSel=e.currentTarget.elements.eligible_graduation_years;const body={company_name:f.get('company_name').trim(),role_title:f.get('role_title').trim(),job_type:f.get('job_type'),location:f.get('location').trim(),package_min_lpa:f.get('package_min_lpa')?Number(f.get('package_min_lpa')):undefined,package_max_lpa:f.get('package_max_lpa')?Number(f.get('package_max_lpa')):undefined,package_currency:f.get('package_currency')||undefined,min_cgpa:f.get('min_cgpa')?Number(f.get('min_cgpa')):undefined,max_attempts:f.get('max_attempts')?Number(f.get('max_attempts')):undefined,drive_date:isoDateToDDMMYYYY(f.get('drive_date')),application_deadline:isoDateToDDMMYYYY(f.get('application_deadline')),window_start:localDateTimeToDDMMYYYYAMPM(f.get('window_start')),window_end:localDateTimeToDDMMYYYYAMPM(f.get('window_end')),interview_duration_minutes:Number(f.get('interview_duration_minutes')),status:f.get('status'),eligible_departments:checkedValues(e.currentTarget,'eligible_departments'),eligible_programs:[...programSel.selectedOptions].map(x=>x.value),eligible_graduation_years:[...yearSel.selectedOptions].map(x=>Number(x.value))};btn.disabled=true;btn.textContent='Saving…';try{await api(`/api/college/drives/${d.id}`,{method:'PUT',body});const jd=qs('#setup-jd').value.trim();if(jd&&jd!==(d.jd_raw_text||'').trim())await api(`/api/college/drives/${d.id}/jd`,{method:'POST',body:{raw_text:jd}});msg.className='notice success';msg.textContent='Drive configuration saved.';state.drives=[];toast('Drive saved.');setTimeout(()=>renderDrive(d.id,routeInfo().params),400)}catch(x){msg.className='form-error';msg.textContent=x.message}finally{btn.disabled=false;btn.textContent='Save configuration'}};qs('#delete-drive').onclick=async()=>{if(!confirm('Delete this drive? This cannot be undone.'))return;try{await api(`/api/college/drives/${d.id}`,{method:'DELETE'});state.drives=[];toast('Drive deleted.');go('/drives')}catch(x){toast(x.message,'error')}}}

  async function drawDriveSetup(root,d){
    // The persona library (4 fixed defaults, plus whatever custom agents
    // this college has built per round) so each round's row can offer a
    // dropdown of "Default" + this college's own saved agents for that
    // round — a per-DRIVE choice, independent of whichever persona the
    // college has marked "active" elsewhere.
    let agentsData={agents:[]};
    try{agentsData=await api('/api/college/agents')}catch(e){/* setup still usable with every round defaulted */}
    drawDriveSetupLegacy(root,d);
    const form=qs('#setup-form');
    const mainPanel=form.querySelector('section.surface.panel');
    const agentHost=document.createElement('div');
    mainPanel.querySelector('.form-grid').before(agentHost);
    const agentPanel=buildAgentSelectionBlock(agentHost,agentsData,Array.isArray(d.agent_selection)?d.agent_selection:null);
    form.onsubmit=async e=>{
      e.preventDefault();
      if(!agentPanel.validate())return;
      const f=new FormData(form),btn=qs('#setup-save'),msg=qs('#setup-msg'),jd=qs('#setup-jd').value.trim();
      const body={
        company_name:f.get('company_name').trim(),role_title:f.get('role_title').trim(),job_type:f.get('job_type'),
        location:f.get('location').trim(),
        package_min_lpa:f.get('package_min_lpa')?Number(f.get('package_min_lpa')):undefined,
        package_max_lpa:f.get('package_max_lpa')?Number(f.get('package_max_lpa')):undefined,
        package_currency:f.get('package_currency')||undefined,
        min_cgpa:f.get('min_cgpa')?Number(f.get('min_cgpa')):undefined,
        max_attempts:f.get('max_attempts')?Number(f.get('max_attempts')):undefined,
        drive_date:isoDateToDDMMYYYY(f.get('drive_date')),application_deadline:isoDateToDDMMYYYY(f.get('application_deadline')),
        window_start:localDateTimeToDDMMYYYYAMPM(f.get('window_start')),window_end:localDateTimeToDDMMYYYYAMPM(f.get('window_end')),
        interview_duration_minutes:Number(f.get('interview_duration_minutes')),status:f.get('status'),
        eligible_departments:checkedValues(form,'eligible_departments'),
        eligible_programs:[...form.elements.eligible_programs.selectedOptions].map(x=>x.value),
        eligible_graduation_years:[...form.elements.eligible_graduation_years.selectedOptions].map(x=>Number(x.value)),
        agent_selection:agentPanel.getSelection(),
        jd_text:jd&&jd!==(d.jd_raw_text||'').trim()?jd:undefined,
      };
      btn.disabled=true;btn.textContent='Saving…';
      try{
        await api(`/api/college/drives/${d.id}`,{method:'PUT',body});
        msg.className='notice success';msg.textContent='Drive configuration saved.';state.drives=[];toast('Drive saved.');setTimeout(()=>renderDrive(d.id,routeInfo().params),400);
      }catch(x){msg.className='form-error';msg.textContent=x.message}
      finally{btn.disabled=false;btn.textContent='Save configuration'}
    };
  }

  function listStrings(v){if(!Array.isArray(v))return[];return v.map(x=>typeof x==='string'?x:(x?.text||x?.title||x?.label||x?.strength||x?.description||null)).filter(Boolean)}
  function dimensionHtml(detail){const dims=[...(Array.isArray(detail?.core_dimensions)?detail.core_dimensions:[]),...(Array.isArray(detail?.domain_dimensions)?detail.domain_dimensions:[])];if(!dims.length)return'';return `<div class="dimension-list">${dims.map(x=>{const pct=x.percentage==null?null:Number(x.percentage);const label=x.label||statusLabel(x.dimension||'Competency');return `<div class="dimension-row"><div><strong>${esc(label)}</strong><span>${pct==null?'Not assessed':`${Math.round(pct)}/100`}</span></div><div class="meter"><span style="width:${pct==null?0:Math.max(0,Math.min(100,pct))}%"></span></div></div>`}).join('')}</div>`}
  function agentHtml(detail){const a=Array.isArray(detail?.agent_breakdown)?detail.agent_breakdown:[];if(!a.length)return'';return `<div class="agent-mini-grid">${a.map((x,i)=>`<div><span>${esc(String(x.agent_type||`Panel ${i+1}`).toUpperCase())}</span><strong>${score(x.sub_score)}</strong><small>${esc(x.readiness||x.status||'Assessment recorded')}</small></div>`).join('')}</div>`}
  function proctoringHtml(detail){const p=detail?.proctoring_score;if(!p||typeof p.overall_score!=='number')return'';const subs=p.sub_scores||{},flags=detail?.proctoring_flags||{},events=Object.entries(flags.by_type||{}).filter(([,count])=>Number(count)>0),total=Number.isFinite(Number(flags.total))?Number(flags.total):Number(p.total_events||0),review=p.status==='review';const status=p.status==='clean'?'No integrity concerns':review?'Officer review suggested':'Minor signals recorded';const labels={face_presence:'Face presence',gaze_tracking:'Gaze tracking',environment:'Environment',browser_behavior:'Browser behavior'};return `<section class="integrity-panel ${review?'integrity-review':''}"><header><div><span class="context-label">Proctoring integrity</span><h4>${Math.round(Number(p.overall_score))}<small>/100</small></h4></div>${statusPill(status,review?'amber':p.status==='clean'?'green':'neutral')}</header><p>${total?`${total} integrity ${total===1?'event was':'events were'} recorded for officer review.`:'No scored integrity events were recorded during this interview.'}</p><div class="agent-mini-grid integrity-mini-grid">${Object.entries(labels).map(([key,label])=>`<div><span>${esc(label)}</span><strong>${score(subs[key])}</strong><small>out of 100</small></div>`).join('')}</div>${events.length?`<div class="integrity-events"><strong>Recorded signals</strong>${events.map(([type,count])=>`<span>${esc(statusLabel(type))}<b>${Number(count)}</b></span>`).join('')}</div>`:''}<small class="integrity-note">Advisory review signal only. Consider it alongside interview evidence; it never makes an automated placement decision.</small></section>`}
  function requirementAssessmentHtml(detail){const items=Array.isArray(detail?.requirement_assessment)?detail.requirement_assessment:[];if(!items.length)return'';return `<div class="question-evidence"><article><h4>JD requirement assessment</h4><div class="timeline">${items.map(x=>`<div class="timeline-item"><span></span><div><strong>${esc(x.name||x.skill||'Requirement')} · ${esc(statusLabel(x.status||'not assessed'))}</strong><small>${esc(statusLabel(x.priority||'requirement'))} · Resume: ${esc(statusLabel(x.resume_status||'unknown'))}${x.exposure?` · Exposure: ${esc(statusLabel(x.exposure))}`:''}${x.knowledge_signal?` · Knowledge: ${esc(statusLabel(x.knowledge_signal))}`:''}${x.claim_origin?` · Claim: ${esc(statusLabel(x.claim_origin))}`:''}</small></div></div>`).join('')}</div></article></div>`}
  function adminReportHtml(report){if(!report)return `<section class="drawer-section"><div class="notice">No Stage 6 report is available for this drive yet.</div></section>`;const d=report.detail||{},strengths=listStrings(d.strengths),imp=Array.isArray(d.priority_improvement_areas)?d.priority_improvement_areas:[];return `<section class="drawer-section">${sectionTitle('Stage 6 assessment',`${report.company_name||'Placement'} · ${report.role_title||report.label}`,statusPill(report.readiness||'Assessment'))}${d.executive_summary?`<p class="report-summary">${esc(d.executive_summary)}</p>`:''}${dimensionHtml(d)}${agentHtml(d)}${proctoringHtml(d)}${requirementAssessmentHtml(d)}${strengths.length?`<div class="question-evidence"><article><h4>Evidence-backed strengths</h4><p>${strengths.slice(0,4).map(esc).join(' · ')}</p></article></div>`:''}${imp.length?`<div class="question-evidence">${imp.slice(0,3).map(x=>`<article><h4>${esc(x.focus||`Priority ${x.priority||''}`)}</h4><p>${esc(x.problem||'')}${Array.isArray(x.actions)&&x.actions.length?` ${esc(x.actions.join(' · '))}`:''}</p></article>`).join('')}</div>`:''}</section>`}

  async function openCandidate(driveId,candidate){if(!candidate)return;overlay.innerHTML=`<div class="drawer-layer"><button id="drawer-scrim" class="drawer-scrim" aria-label="Close"></button><aside class="candidate-drawer"><header class="drawer-header"><div><span class="context-label">Candidate intelligence</span><h2>${esc(candidate.full_name)}</h2><p>${esc(candidate.roll_number)} · ${esc(candidate.department_code)} · CGPA ${candidate.cgpa??'—'}</p></div><button id="drawer-close" class="icon-button">×</button></header><div id="drawer-content" class="drawer-loading">Loading candidate evidence…</div></aside></div>`;const close=()=>overlay.innerHTML='';qs('#drawer-close').onclick=close;qs('#drawer-scrim').onclick=close;const root=qs('#drawer-content');try{const [decisions,reportsBundle,attempts]=await Promise.all([api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/decision`),api(`/api/college/students/${candidate.student_id}/reports`),api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/attempts`)]);const report=(reportsBundle.reports||[]).find(r=>r.drive_id===driveId)||null;let publication=decisions.publication||candidate.publication||{state:'hidden'};let current=decisions.decision;root.className='drawer-body';root.innerHTML=`<section class="candidate-score-strip">${candidateScore('Fit Score',candidate.ranking_score,candidate.decision_support?.comparable?(candidate.rank?`Rank #${candidate.rank}`:'Comparable'):'Review required')}${candidateScore('Interview',candidate.overall_score,'out of 100')}${candidateScore('Domain',candidate.scores?.domain,'out of 100')}${candidateScore('Communication',candidate.scores?.communication,'out of 100')}</section><section class="drawer-section">${sectionTitle('Decision intelligence','AI recommendation is advisory. The college decision is the human record.')}<div class="decision-grid"><div class="decision-card ai"><span>AI recommendation</span><strong>${esc(candidate.recommendation)}</strong><small>Confidence: ${esc(candidate.recommendation_confidence??'—')}</small>${candidate.recommendation_reasons?.length?`<ul>${candidate.recommendation_reasons.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${candidate.recommendation_risks?.length?`<div class="risk-list">${candidate.recommendation_risks.slice(0,3).map(x=>`<p>! ${esc(x)}</p>`).join('')}</div>`:''}</div><div class="decision-card"><span>College decision</span><strong id="decision-current">${current?esc(current.decision.toUpperCase()):'Not decided'}</strong><small id="decision-date">${current?fmtDateTime(current.decided_at):'No human decision recorded'}</small><div class="choice-row" id="choice-row">${['shortlist','hold','reject'].map(x=>`<button type="button" data-decision="${x}" class="choice ${current?.decision===x?'selected':''} ${x}">${statusLabel(x)}</button>`).join('')}</div><textarea id="decision-note" class="field-textarea compact" placeholder="Decision note (optional)">${esc(current?.note||'')}</textarea><button id="save-decision" class="button button--primary">Save college decision</button></div></div></section><section class="drawer-section">${sectionTitle('Interview attempts',`${(attempts.attempts||[]).length} of ${attempts.max_attempts} used`,'<button id="grant-attempt" type="button" class="button button--secondary">Grant another attempt</button>')}<div class="timeline">${(attempts.attempts||[]).map(a=>`<div class="timeline-item"><span></span><div><strong>Attempt ${a.attempt_number}${attempts.best_attempt&&attempts.best_attempt.attempt_number===a.attempt_number?' · Best':''}</strong><small>${a.completed_at?fmtDateTime(a.completed_at):'Not completed'} · ${esc(statusLabel(a.evaluation_status||'pending'))}</small>${a.overall_score!=null?`<p>Score: ${score(a.overall_score)}${a.readiness?` · ${esc(a.readiness)}`:''}</p>`:''}</div></div>`).join('')||'<p class="footnote">No attempts recorded yet.</p>'}</div><div id="grant-attempt-form" class="hidden" style="margin-top:10px"><div class="schedule-row"><input id="attempt-override" class="field-input" type="number" min="1" placeholder="New cap (optional)"/><input id="attempt-deadline" class="field-input" type="datetime-local"/><button id="grant-attempt-confirm" class="button button--primary">Confirm</button></div><p class="footnote" style="margin:6px 0 0">Leave the cap blank to reopen within the existing limit; set it only to raise THIS student's personal cap without changing the drive-wide default.</p></div></section><section class="drawer-section"><div id="publication-head">${sectionTitle('Student result publication','Independent of evaluation readiness and the college decision.',statusPill(publication.state))}</div><div id="publication-body"></div></section>${adminReportHtml(report)}${report?.session_id?`<section class="drawer-section">${sectionTitle('Interview evidence','Review recorded question/answer turns only when needed.','<button id="load-transcript" class="button button--secondary">Load transcript</button>')}<div id="transcript"></div></section>`:''}${(decisions.history||[]).length?`<section class="drawer-section">${sectionTitle('Decision history','Every recorded human decision for this candidate and drive.')}<div class="timeline">${decisions.history.map(h=>`<div class="timeline-item"><span></span><div><strong>${esc(h.decision.toUpperCase())}</strong><small>${fmtDateTime(h.decided_at)}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</div></div>`).join('')}</div></section>`:''}`;
      let choice=current?.decision||'shortlist';qsa('#choice-row .choice').forEach(b=>b.onclick=()=>{qsa('#choice-row .choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');choice=b.dataset.decision});qs('#save-decision').onclick=async()=>{const btn=qs('#save-decision');btn.disabled=true;try{const r=await api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/decision`,{method:'PUT',body:{decision:choice,note:qs('#decision-note').value.trim()||null}});current=r.decision||{decision:choice,decided_at:new Date().toISOString(),note:qs('#decision-note').value.trim()};qs('#decision-current').textContent=choice.toUpperCase();qs('#decision-date').textContent=fmtDateTime(current.decided_at);candidate.officer_decision=current.decision;candidate.decided_at=current.decided_at;refreshCandidatePills(candidate);toast('College decision saved.')}catch(x){toast(x.message,'error')}finally{btn.disabled=false}};
      qs('#grant-attempt').onclick=()=>qs('#grant-attempt-form').classList.toggle('hidden');
      qs('#grant-attempt-confirm').onclick=async()=>{
        const btn=qs('#grant-attempt-confirm');const overrideVal=qs('#attempt-override').value;const deadlineVal=qs('#attempt-deadline').value;
        if(!confirm(`Grant ${esc(candidate.full_name)} another attempt at this drive?`))return;
        btn.disabled=true;
        try{
          await api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/reopen`,{method:'PUT',body:{max_attempts_override:overrideVal?Number(overrideVal):undefined,new_deadline_at:deadlineVal?new Date(deadlineVal).toISOString():undefined}});
          toast('Attempt reopened.');
          openCandidate(driveId,candidate);
        }catch(x){toast(x.message,'error');btn.disabled=false}
      };
      const drawPub=()=>{qs('#publication-head').innerHTML=sectionTitle('Student result publication','Independent of evaluation readiness and the college decision.',statusPill(publication.state));const b=qs('#publication-body');if(publication.state==='released'){b.innerHTML=`<div class="notice success">Released to student ${publication.released_at?`on ${fmtDateTime(publication.released_at)}`:''}.</div>`;return}b.innerHTML=`<div class="publication-actions"><button id="release-now" class="button button--primary">Release now</button><div class="schedule-row"><input id="release-time" class="field-input" type="datetime-local"/><button id="schedule-release" class="button button--secondary">Schedule</button></div></div>${publication.state==='scheduled'?`<div class="notice warn" style="margin-top:10px">Scheduled for ${fmtDateTime(publication.scheduled_for)} <button id="clear-release" class="text-button">Cancel schedule</button></div>`:''}`;qs('#release-now').onclick=async()=>{if(!confirm('Release this placement result to the student now?'))return;try{const r=await api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/release`,{method:'PUT'});publication=r.publication||{state:'released'};candidate.publication=publication;refreshCandidatePills(candidate);drawPub();toast('Result released to student.')}catch(x){toast(x.message,'error')}};qs('#schedule-release').onclick=async()=>{const v=qs('#release-time').value;if(!v){toast('Choose a future release date and time.','error');return}try{const r=await api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/release/schedule`,{method:'PUT',body:{scheduled_for:new Date(v).toISOString()}});publication=r.publication||{state:'scheduled',scheduled_for:new Date(v).toISOString()};candidate.publication=publication;refreshCandidatePills(candidate);drawPub();toast('Result release scheduled.')}catch(x){toast(x.message,'error')}};qs('#clear-release')?.addEventListener('click',async()=>{try{const r=await api(`/api/college/drives/${driveId}/candidates/${candidate.student_id}/release/schedule`,{method:'DELETE'});publication=r.publication||{state:'hidden'};candidate.publication=publication;refreshCandidatePills(candidate);drawPub();toast('Release schedule cancelled.')}catch(x){toast(x.message,'error')}})};drawPub();
      if(report?.session_id)qs('#load-transcript').onclick=async()=>{const btn=qs('#load-transcript'),t=qs('#transcript');btn.disabled=true;btn.textContent='Loading…';try{const r=await api(`/api/college/students/${candidate.student_id}/reports/${report.session_id}/transcript`);t.innerHTML=`<div class="transcript-list">${(r.turns||[]).map(turn=>`<article class="transcript-turn"><header><span>${esc(String(turn.agent_type||'Interview').toUpperCase())}</span><small>${esc(turn.kind||'question')}</small></header><h4>${esc(turn.question_text||'Interview turn')}</h4><p>${esc(turn.transcript||'No transcript was captured for this turn.')}</p>${turn.has_audio?`<audio controls preload="none" src="/api/college/students/${attr(candidate.student_id)}/reports/${attr(report.session_id)}/turns/${attr(turn.turn_id)}/audio"></audio>`:''}</article>`).join('')}</div>`;btn.textContent='Refresh transcript'}catch(x){t.innerHTML=`<div class="form-error">${esc(x.message)}</div>`;btn.textContent='Load transcript'}finally{btn.disabled=false}}
    }catch(e){root.className='drawer-body';root.innerHTML=`<div class="form-error">${esc(e.message||'Could not load candidate details.')}</div>`}}
  function candidateScore(label,value,helper){return `<div><span>${esc(label)}</span><strong>${score(value)}</strong><small>${esc(helper||'out of 100')}</small></div>`}
  function refreshCandidatePills(candidate){const sid=attr(candidate.student_id);qsa(`.decision-pill[data-student="${sid}"]`).forEach(el=>el.innerHTML=statusPill(candidate.officer_decision||'Undecided'));qsa(`.publication-pill[data-student="${sid}"]`).forEach(el=>el.innerHTML=statusPill(candidate.publication?.state||'hidden'))}
  async function renderReports(){await loadFoundation();const currentDrive=routeInfo().params.get('drive')||state.drives[0]?.id||'';app.innerHTML=shell({eyebrow:'Interview intelligence',title:'Interview Reports',description:'Open completed placement evaluations by drive. This page uses the selected drive’s real Stage 6 evidence instead of inventing a college-wide aggregate.',body:`<div class="toolbar surface"><label class="compact-select">Drive<select id="report-drive">${state.drives.map(d=>`<option value="${attr(d.id)}" ${d.id===currentDrive?'selected':''}>${esc(d.company_name)} — ${esc(d.role_title)}</option>`).join('')}</select></label><div class="search-field">⌕<input id="report-search" placeholder="Search candidate…"/></div></div><div id="report-results"></div>`});bindShell();if(!state.drives.length){qs('#report-results').innerHTML=empty('No drive reports yet','Placement interview reports appear here after a drive exists and Stage 6 produces candidate evaluations.');return}const load=async id=>{const root=qs('#report-results');root.innerHTML='<div class="skeleton"></div>';try{const data=await fetchAllRanking(id);root.dataset.drive=id;root._data=data;drawReportRows(data,id)}catch(e){root.innerHTML=`<div class="form-error">${esc(e.message)}</div>`}};qs('#report-drive').onchange=e=>load(e.target.value);qs('#report-search').oninput=()=>{const root=qs('#report-results');if(root._data)drawReportRows(root._data,root.dataset.drive)};await load(currentDrive)}
  function drawReportRows(data,driveId){const q=qs('#report-search')?.value.toLowerCase()||'';const rows=(data.candidates||[]).filter(c=>(c.overall_score!=null||c.evaluation_status!=='incomplete')&&`${c.full_name} ${c.roll_number}`.toLowerCase().includes(q));const root=qs('#report-results');root.innerHTML=`<div class="surface table-shell"><table class="data-table"><thead><tr><th>Candidate</th><th>Interview</th><th>Fit Score</th><th>Readiness</th><th>AI recommendation</th><th>Decision</th><th>Publication</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong><span>${esc(c.roll_number)} · ${esc(c.department_code)}</span></td><td><strong>${score(c.overall_score)}</strong></td><td><strong>${score(c.ranking_score)}</strong></td><td>${statusPill(c.readiness||'Not assessed')}</td><td>${esc(c.recommendation)}</td><td><span class="decision-pill" data-student="${attr(c.student_id)}">${statusPill(c.officer_decision||'Undecided')}</span></td><td><span class="publication-pill" data-student="${attr(c.student_id)}">${statusPill(c.publication?.state||'hidden')}</span></td><td><button class="row-action report-open" data-student="${attr(c.student_id)}">Review →</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty-table">No evaluated reports match this view.</div>'}</div>`;qsa('.report-open').forEach(b=>b.onclick=()=>openCandidate(driveId,rows.find(c=>c.student_id===b.dataset.student)))}

  const STUDENT_PAGE_SIZE=25;
  // GET /api/college/students returns {items,total,...} (server-paginated,
  // limit strictly validated <=100 -- 200 always 422'd) not a flat array.
  async function renderStudents(){await loadFoundation();app.innerHTML=shell({eyebrow:'Student roster',title:'Student Directory',description:'Institution-managed student records used for eligibility, placement assignments, and candidate history.',actions:'<a class="button button--secondary" href="#/students/import">Import roster</a><button id="add-student" class="button button--primary">+ Add student</button>',body:`<div class="toolbar surface"><div class="search-field">⌕<input id="student-search" placeholder="Search name, roll number or email…"/></div><select id="student-dept" class="toolbar-select"><option value="">All departments</option>${state.departments.map(d=>`<option value="${attr(d.code)}">${esc(d.display_name)} (${esc(d.code)})</option>`).join('')}</select><span id="student-count" class="toolbar-note"></span></div><div id="student-results"><div class="skeleton"></div></div>`});bindShell();let timer,page=1;const load=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=qs('#student-search').value.trim(),dept=qs('#student-dept').value,root=qs('#student-results');try{const data=await api(`/api/college/students?limit=${STUDENT_PAGE_SIZE}&offset=${(page-1)*STUDENT_PAGE_SIZE}${q?`&q=${encodeURIComponent(q)}`:''}${dept?`&department=${encodeURIComponent(dept)}`:''}`);const rows=data.items||[];root._rows=rows;drawStudents(rows,data.total||0,page,(n)=>{page=n;load()});qs('#student-count').textContent=`${data.total||0} total`}catch(e){root.innerHTML=`<div class="form-error">${esc(e.message)}</div>`}},100)};qs('#student-search').oninput=()=>{page=1;load()};qs('#student-dept').onchange=()=>{page=1;load()};qs('#add-student').onclick=()=>openStudentEditor(null,load);load()}
  function drawStudents(rows,total,page,onPage){const root=qs('#student-results');const pageCount=Math.max(1,Math.ceil(total/STUDENT_PAGE_SIZE));const pager=`<div class="pagination"><button id="students-prev" class="button button--secondary" ${page<=1?'disabled':''}>Previous</button><span>Page ${page} of ${pageCount}</span><button id="students-next" class="button button--secondary" ${page>=pageCount?'disabled':''}>Next</button></div>`;root.innerHTML=rows.length?`<div class="surface table-shell"><table class="data-table"><thead><tr><th>Student</th><th>Program</th><th>Department</th><th>CGPA</th><th>Graduation</th><th>Status</th><th>Contact</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.full_name)}</strong><span>${esc(s.roll_number)}</span></td><td>${esc(s.program)}</td><td>${esc(s.department_code)}</td><td>${s.cgpa??'—'}</td><td>${s.graduation_year??'—'}</td><td>${statusPill(s.status)}</td><td><span class="small-copy">${esc(s.email)}<br/>${esc(s.phone||'—')}</span></td><td><div class="row-actions"><button class="row-action student-history" data-id="${attr(s.id)}">History</button><button class="row-action student-edit" data-id="${attr(s.id)}">Edit</button></div></td></tr>`).join('')}</tbody></table></div>${pager}`:empty('No students found','Add a student or import the placement roster.');qsa('.student-edit').forEach(b=>b.onclick=()=>openStudentEditor(rows.find(s=>s.id===b.dataset.id),()=>renderStudents()));qsa('.student-history').forEach(b=>b.onclick=()=>openStudentHistory(rows.find(s=>s.id===b.dataset.id)));qs('#students-prev')?.addEventListener('click',()=>onPage(page-1));qs('#students-next')?.addEventListener('click',()=>onPage(page+1))}
  function programOptions(selected){return state.catalog.map(p=>`<option value="${attr(p.code)}" ${p.code===selected?'selected':''}>${esc(p.display_name)}</option>`).join('')}
  function deptOptions(program,selected){return (state.catalog.find(p=>p.code===program)?.departments||[]).map(d=>`<option value="${attr(d.code)}" ${d.code===selected?'selected':''}>${esc(d.display_name)} (${esc(d.code)})</option>`).join('')}
  function openStudentEditor(student,onSaved){const isNew=!student,defaultProgram=student?.program||state.catalog[0]?.code||'B.Tech',defaultDept=student?.department_code||state.catalog.find(p=>p.code===defaultProgram)?.departments?.[0]?.code||'';overlay.innerHTML=`<div class="modal-layer"><form id="student-form" class="modal-card modal-card--wide"><div class="modal-heading"><div><span class="context-label">${isNew?'New roster record':'Edit roster record'}</span><h2>${isNew?'Add student':'Update student'}</h2><p>Academic and identity fields remain placement-cell managed.</p></div><button id="student-close" type="button" class="icon-button">×</button></div><div class="form-grid two">${isNew?field('Roll number',`<input name="roll_number" required class="field-input" value=""/>`):''}${field('Full name',`<input name="full_name" required class="field-input" value="${attr(student?.full_name||'')}"/>`)}${field('Email',`<input name="email" required type="email" class="field-input" value="${attr(student?.email||'')}"/>`)}${field('Phone',`<input name="phone" required class="field-input" value="${attr(student?.phone||'')}"/>`)}${field('Program',`<select id="student-program" name="program" class="field-select">${programOptions(defaultProgram)}</select>`)}${field('Department',`<select id="student-department" name="department_code" class="field-select">${deptOptions(defaultProgram,defaultDept)}</select>`)}${field('CGPA',`<input name="cgpa" required min="0" max="10" step=".01" type="number" class="field-input" value="${attr(student?.cgpa??0)}"/>`)}${field('Graduation year',`<input name="graduation_year" required min="2000" max="2100" type="number" class="field-input" value="${attr(student?.graduation_year??new Date().getFullYear()+1)}"/>`)}${field('Batch label',`<input name="batch_label" class="field-input" value="${attr(student?.batch_label||'')}" placeholder="Auto-calculated when blank"/>`)}${field('Status',`<select name="status" class="field-select">${['active','inactive','placed'].map(x=>`<option ${student?.status===x||(!student&&x==='active')?'selected':''} value="${x}">${statusLabel(x)}</option>`).join('')}</select>`)}</div><div id="student-error" class="form-error hidden"></div><div class="modal-actions">${!isNew?'<button id="archive-student" type="button" class="button button--danger">Archive</button>':''}<button id="student-cancel" type="button" class="button button--secondary">Cancel</button><button id="student-save" class="button button--primary">Save student</button></div></form></div>`;const close=()=>overlay.innerHTML='';qs('#student-close').onclick=close;qs('#student-cancel').onclick=close;qs('#student-program').onchange=e=>qs('#student-department').innerHTML=deptOptions(e.target.value,'');if(!isNew)qs('#archive-student').onclick=async()=>{if(!confirm('Archive this student from the active roster?'))return;try{await api(`/api/college/students/${student.id}`,{method:'DELETE'});close();toast('Student archived.');onSaved?.()}catch(e){toast(e.message,'error')}};qs('#student-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={full_name:f.get('full_name').trim(),email:f.get('email').trim(),phone:f.get('phone').trim(),program:f.get('program'),department_code:f.get('department_code'),cgpa:Number(f.get('cgpa')),graduation_year:Number(f.get('graduation_year')),batch_label:f.get('batch_label').trim()||null,status:f.get('status')};if(isNew)body.roll_number=f.get('roll_number').trim();const btn=qs('#student-save'),err=qs('#student-error');btn.disabled=true;btn.textContent='Saving…';try{await api(isNew?'/api/college/students':`/api/college/students/${student.id}`,{method:isNew?'POST':'PUT',body});close();toast(isNew?'Student added.':'Student updated.');onSaved?.()}catch(x){err.textContent=x.message;err.classList.remove('hidden')}finally{btn.disabled=false;btn.textContent='Save student'}}}
  async function openStudentHistory(student){overlay.innerHTML=`<div class="drawer-layer"><button id="drawer-scrim" class="drawer-scrim"></button><aside class="candidate-drawer"><header class="drawer-header"><div><span class="context-label">Student history</span><h2>${esc(student.full_name)}</h2><p>${esc(student.roll_number)} · ${esc(student.department_code)}</p></div><button id="drawer-close" class="icon-button">×</button></header><div id="student-history-body" class="drawer-loading">Loading interview history…</div></aside></div>`;const close=()=>overlay.innerHTML='';qs('#drawer-close').onclick=close;qs('#drawer-scrim').onclick=close;const root=qs('#student-history-body');try{const data=await api(`/api/college/students/${student.id}/reports`);const reports=data.reports||[];root.className='drawer-body';root.innerHTML=`<section class="candidate-score-strip">${infoCard('CGPA',student.cgpa??'—')}${infoCard('Program',student.program)}${infoCard('Graduation',student.graduation_year??'—')}${infoCard('Status',statusLabel(student.status))}</section><section class="drawer-section">${sectionTitle('Interview history','Placement drives and self-practice interviews stored for this student.')} ${reports.length?`<div class="history-cards">${reports.map(r=>`<article><div><strong>${esc(r.label)}</strong><span>${r.source==='drive'?'Placement':'Practice'} · ${fmtDateTime(r.completed_at)}</span></div><div><b>${score(r.overall_score)}</b>${statusPill(r.readiness||'Not assessed')}</div></article>`).join('')}</div>`:'<div class="notice">No completed interview reports yet.</div>'}</section>`}catch(e){root.className='drawer-body';root.innerHTML=`<div class="form-error">${esc(e.message)}</div>`}}
  function infoCard(label,value){return `<div><span>${esc(label)}</span><strong class="small-value">${esc(value)}</strong></div>`}
  function renderImport(){app.innerHTML=shell({eyebrow:'Student roster',title:'Import Students',description:'Bulk-create or update roster records using the backend CSV/XLSX importer and academic catalog validation.',actions:'<a class="button button--secondary" href="/api/college/students/template">Download Excel template</a>',body:`<div class="import-layout"><section class="surface panel">${sectionTitle('Upload roster','.xlsx or .csv · maximum 10 MB')}<label id="dropzone" class="dropzone"><input id="roster-file" type="file" accept=".xlsx,.csv"/><span class="drop-icon">↑</span><strong id="file-name">Drop an Excel/CSV roster here</strong><p id="file-meta">or click to choose a file</p></label><div id="import-error" class="form-error hidden"></div><button id="import-btn" class="button button--primary" disabled>Import roster</button></section><aside><section class="surface panel">${sectionTitle('What the importer validates','It does not silently fabricate academic data.')}<ul class="check-list"><li>Program ↔ department mapping</li><li>CGPA must be on a 0–10 scale</li><li>Graduation year must be valid</li><li>Email, phone and identity fields</li><li>Blank status preserves an existing inactive/placed status</li></ul></section><div id="import-result"></div></aside></div>`});bindShell();let file=null;const input=qs('#roster-file'),drop=qs('#dropzone'),btn=qs('#import-btn');const select=f=>{file=f||null;qs('#file-name').textContent=file?file.name:'Drop an Excel/CSV roster here';qs('#file-meta').textContent=file?`${Math.round(file.size/1024)} KB selected`:'or click to choose a file';btn.disabled=!file};input.onchange=e=>select(e.target.files?.[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');select(e.dataTransfer.files?.[0])};btn.onclick=async()=>{if(!file)return;btn.disabled=true;btn.textContent='Importing…';const fd=new FormData();fd.append('file',file);try{const r=await api('/api/college/students/upload',{method:'POST',body:fd});toast('Roster import finished.');qs('#import-result').innerHTML=`<section class="surface panel result-panel">${sectionTitle('Import result',statusLabel(r.status))}<div class="metric-grid three">${metric('New students',r.records_created??'—','Brand-new roster rows')}${metric('Existing students updated',r.records_updated??'—','Overwrote a prior record')}${metric('Errors',r.errors_count,'Rows needing attention')}</div><div class="metric-grid two" style="margin-top:12px">${metric('Catalog rows saved',r.catalog_rows_saved,'Academic records')}${metric('Warnings',r.warnings_count,'Review suggested')}</div>${r.errors_sample?.length?`<div class="issue-list"><strong>Rows needing attention</strong>${r.errors_sample.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}${r.warnings_sample?.length?`<div class="issue-list warning"><strong>Warnings</strong>${r.warnings_sample.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}</section>`}catch(e){const er=qs('#import-error');er.textContent=e.message;er.classList.remove('hidden')}finally{btn.disabled=false;btn.textContent='Import roster'}}}

  async function renderAcademic(){await loadFoundation();app.innerHTML=shell({eyebrow:'Configuration',title:'Academic Setup',description:'Programs and department mappings used to validate student records and placement-drive eligibility.',actions:'<button id="add-program" class="button button--primary">+ Add program</button>',body:`<div class="info-banner"><strong>Academic structure is operational configuration.</strong><span>It validates roster records and eligibility. It does not increase or decrease interview ranking.</span></div><div id="academic-grid" class="academic-grid"></div>`});bindShell();const draw=()=>{qs('#academic-grid').innerHTML=state.catalog.length?state.catalog.map(p=>`<section class="surface academic-card"><header><div><span class="program-code">${esc(p.code)}</span><h3>${esc(p.display_name)}</h3><p>${p.duration_years} year program · ${(p.departments||[]).length} departments</p></div><div class="row-actions"><button class="row-action edit-program" data-code="${attr(p.code)}">Edit</button><button class="row-action add-dept" data-code="${attr(p.code)}">+ Department</button><button class="row-action danger delete-program" data-code="${attr(p.code)}">Delete</button></div></header><div class="department-list">${(p.departments||[]).map(d=>`<div><div><strong>${esc(d.display_name)}</strong><span>${esc(d.code)}</span></div><button class="icon-button tiny delete-dept" data-program="${attr(p.code)}" data-code="${attr(d.code)}">×</button></div>`).join('')||'<p class="muted">No departments mapped yet.</p>'}</div></section>`).join(''):empty('Academic catalog is empty','Add your first academic program, then map departments to it.');qsa('.edit-program').forEach(b=>b.onclick=()=>openProgram(state.catalog.find(p=>p.code===b.dataset.code)));qsa('.add-dept').forEach(b=>b.onclick=()=>openDepartment(b.dataset.code));qsa('.delete-program').forEach(b=>b.onclick=async()=>{if(!confirm(`Delete program ${b.dataset.code}? The backend will block this if it is in use.`))return;try{await api(`/api/college/academic-catalog/programs/${encodeURIComponent(b.dataset.code)}`,{method:'DELETE'});state.catalog=[];await loadFoundation();draw();toast('Program deleted.')}catch(e){toast(e.message,'error')}});qsa('.delete-dept').forEach(b=>b.onclick=async()=>{if(!confirm(`Remove department ${b.dataset.code} from ${b.dataset.program}? This does not affect existing students already in this department — it only blocks NEW students from being added under this program+department pairing.`))return;try{await api(`/api/college/academic-catalog/programs/${encodeURIComponent(b.dataset.program)}/departments/${encodeURIComponent(b.dataset.code)}`,{method:'DELETE'});state.catalog=[];state.departments=[];await loadFoundation();draw();toast('Department mapping removed.')}catch(e){toast(e.message,'error')}})};draw();qs('#add-program').onclick=openProgram;function openProgram(existing){overlay.innerHTML=`<div class="modal-layer"><form id="program-form" class="modal-card"><div class="modal-heading"><div><span class="context-label">Academic setup</span><h2>${existing?'Edit program':'Add program'}</h2></div><button id="modal-close" type="button" class="icon-button">×</button></div>${field('Program code',`<input name="code" required class="field-input" placeholder="B.Tech" value="${attr(existing?.code||'')}" ${existing?'readonly':''}/>`,existing?'The code identifies this program everywhere and cannot be changed here.':'')}${field('Display name',`<input name="display_name" required class="field-input" placeholder="Bachelor of Technology" value="${attr(existing?.display_name||'')}"/>`)}${field('Duration years',`<input name="duration_years" required type="number" min="1" max="8" class="field-input" value="${attr(existing?.duration_years??4)}"/>`)}<div class="modal-actions"><button id="modal-cancel" type="button" class="button button--secondary">Cancel</button><button class="button button--primary">Save program</button></div></form></div>`;const close=()=>overlay.innerHTML='';qs('#modal-close').onclick=close;qs('#modal-cancel').onclick=close;qs('#program-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const code=f.get('code').trim();if(!existing){const collision=state.catalog.find(p=>p.code===code);if(collision&&!confirm(`A program with code "${code}" already exists (${collision.display_name}, ${collision.duration_years} yr) — saving will OVERWRITE it, not create a new program. Continue?`))return}try{await api('/api/college/academic-catalog/programs',{method:'POST',body:{code,display_name:f.get('display_name').trim(),duration_years:Number(f.get('duration_years'))}});close();state.catalog=[];await loadFoundation();draw();toast('Program saved.')}catch(x){toast(x.message,'error')}}}function openDepartment(program){overlay.innerHTML=`<div class="modal-layer"><form id="dept-form" class="modal-card"><div class="modal-heading"><div><span class="context-label">${esc(program)}</span><h2>Add department</h2></div><button id="modal-close" type="button" class="icon-button">×</button></div>${field('Department code','<input name="code" required class="field-input" placeholder="CSE"/>')}${field('Display name','<input name="display_name" required class="field-input" placeholder="Computer Science & Engineering"/>')}<div class="modal-actions"><button id="modal-cancel" type="button" class="button button--secondary">Cancel</button><button class="button button--primary">Save department</button></div></form></div>`;const close=()=>overlay.innerHTML='';qs('#modal-close').onclick=close;qs('#modal-cancel').onclick=close;qs('#dept-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/college/academic-catalog/departments',{method:'POST',body:{program_code:program,code:f.get('code').trim(),display_name:f.get('display_name').trim()}});close();state.catalog=[];state.departments=[];await loadFoundation();draw();toast('Department saved.')}catch(x){toast(x.message,'error')}}}}

  function renderSettings(){const logo=state.me.logo_url||'',color=state.me.primary_color||DEFAULT_BRAND;app.innerHTML=shell({eyebrow:'Configuration',title:'College Settings',description:'The primary color becomes the system accent across both Student and College Placement portals.',body:`<div class="settings-layout"><form id="brand-form" class="surface panel">${sectionTitle('College branding','Applied after authentication using the tenant returned by /api/auth/admin-me.')}<div id="brand-msg" class="hidden"></div>${field('Logo URL',`<input id="brand-logo" class="field-input" value="${attr(logo)}" placeholder="https://college.edu/logo.png"/>`)}${field('Primary color',`<div class="color-field"><input id="color-picker" type="color" value="${attr(color)}"/><input id="brand-color" class="field-input" value="${attr(color)}"/></div>`)}<button id="brand-save" class="button button--primary">Save branding</button></form><aside id="brand-preview" class="surface brand-preview" style="--preview-brand:${attr(color)}"><span class="context-label">Live preview</span><div id="preview-logo" class="preview-logo">${logo?`<img src="${attr(logo)}" alt=""/>`:`<span>${esc(initials(state.me.college_name))}</span>`}</div><h2>${esc(state.me.college_name)}</h2><p>Student and College Placement portals use this tenant identity after sign-in.</p><div class="preview-actions"><button>Primary action</button><span>Selected navigation</span></div></aside></div>`});bindShell();const update=()=>{const c=qs('#brand-color').value,l=qs('#brand-logo').value;qs('#color-picker').value=/^#[0-9a-f]{6}$/i.test(c)?c:DEFAULT_BRAND;qs('#brand-preview').style.setProperty('--preview-brand',c);qs('#preview-logo').innerHTML=l?`<img src="${attr(l)}" alt=""/>`:`<span>${esc(initials(state.me.college_name))}</span>`};qs('#color-picker').oninput=e=>{qs('#brand-color').value=e.target.value;update()};qs('#brand-color').oninput=update;qs('#brand-logo').oninput=update;qs('#brand-form').onsubmit=async e=>{e.preventDefault();const c=qs('#brand-color').value.trim(),l=qs('#brand-logo').value.trim(),msg=qs('#brand-msg');if(!/^#[0-9a-f]{6}$/i.test(c)){msg.className='form-error';msg.textContent='Enter a valid six-digit hex color such as #813DF5.';return}const btn=qs('#brand-save');btn.disabled=true;try{await api('/api/college/branding',{method:'PUT',body:{logo_url:l||null,primary_color:c}});state.me=await api('/api/auth/admin-me');applyBrand();msg.className='notice success';msg.textContent='College branding saved across both portals.';toast('Branding saved.');setTimeout(renderSettings,400)}catch(x){msg.className='form-error';msg.textContent=x.message}finally{btn.disabled=false}}}

  // Custom agents are independent library items. The compatible round is an
  // engine routing choice, not an instruction to inherit that default agent.
  async function renderAgents(){
    app.innerHTML=shell({eyebrow:'Configuration',title:'Interview Agents',description:'Build independent interview agents with their own role, voice, opening, and system prompt. Select them per drive without modifying the four safe defaults.',actions:'<button id="create-agent" class="button button--primary">+ Create agent</button>',body:`<div class="info-banner"><strong>Custom means custom.</strong><span>A Group Discussion agent can use the HR-compatible question lane without inheriting HR prompts; its own system prompt controls question generation and live follow-ups.</span></div><div id="agents-grid" class="agents-library"><div class="skeleton"></div></div>`});
    bindShell();
    let data={agents:[],tracks:[],allowed_voice_ids:[]};
    const refresh=async()=>{data=await api('/api/college/agents');draw()};
    try{data=await api('/api/college/agents')}catch(e){qs('#agents-grid').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;return}
    const draw=()=>{
      const labels=Object.fromEntries(data.tracks.map(track=>[track.track,track.round_label]));
      const defaults=`<section><div class="section-title"><div><h3>Built-in defaults</h3><p>Protected fallbacks. They cannot be edited or deleted.</p></div></div><div class="agent-mini-grid">${data.tracks.map(track=>{const p=track.default_profile||track.effective_profile;return `<div><span>${esc(track.round_label)}</span><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></div>`}).join('')}</div></section>`;
      const custom=data.agents.length?`<section><div class="section-title"><div><h3>Your custom agents</h3><p>Each agent is a separate reusable configuration selected explicitly on a drive.</p></div></div><div class="persona-list">${data.agents.map(a=>`<article class="surface persona-card"><div><div class="persona-title"><strong>${esc(a.name)}</strong><span class="status-pill brand">${esc(labels[a.track]||a.track)} compatible</span></div><span>${esc(a.role)} · ${esc(a.tone)} · ${esc(a.voice_id)}</span><p>${esc(a.personality_prompt.slice(0,220))}${a.personality_prompt.length>220?'…':''}</p></div><div class="row-actions"><button class="row-action edit-agent" data-id="${attr(a.id)}">Edit</button><button class="row-action danger delete-agent" data-id="${attr(a.id)}">Delete</button></div></article>`).join('')}</div></section>`:`<div class="surface notice">No custom agents yet. Create one without changing any default interviewer.</div>`;
      qs('#agents-grid').innerHTML=defaults+custom;
      qsa('.edit-agent').forEach(button=>button.onclick=()=>openAgentEditor(data.agents.find(a=>a.id===button.dataset.id)));
      qsa('.delete-agent').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this interviewer persona?'))return;try{await api(`/api/college/agents/${button.dataset.id}`,{method:'DELETE'});await refresh();toast('Interviewer deleted.')}catch(e){toast(e.message,'error')}});
    };
    draw();
    qs('#create-agent').onclick=()=>openAgentEditor(null,null);
    function openAgentEditor(a,track){
      const isNew=!a,trackInfo=data.tracks.find(x=>x.track===(track||a?.track))||data.tracks[0],defaults=trackInfo.effective_profile;
      const value=a||defaults;
      const voiceOptions=data.allowed_voice_ids.map(v=>`<option value="${attr(v)}" ${value.voice_id===v?'selected':''}>${esc(v)}</option>`).join('');
      overlay.innerHTML=`<div class="modal-layer"><form id="agent-form" class="modal-card"><div class="modal-heading"><div><span class="context-label">Independent agent</span><h2>${isNew?'Create custom agent':'Edit custom agent'}</h2></div><button id="modal-close" type="button" class="icon-button">×</button></div><div id="agent-msg" class="hidden"></div>${field('Agent name','<input name="name" required maxlength="120" class="field-input" placeholder="e.g. Group Discussion Facilitator" value="'+attr(isNew?'':value.name)+'"/>')}${field('Role / title','<input name="role" required maxlength="120" class="field-input" placeholder="e.g. Group Discussion Moderator" value="'+attr(isNew?'':value.role)+'"/>')}${field('Compatible question lane',`<select name="track" class="field-select" ${isNew?'':'disabled'}>${data.tracks.map(x=>`<option value="${attr(x.track)}" ${x.track===trackInfo.track?'selected':''}>${esc(x.round_label)}</option>`).join('')}</select>`,'Routes the agent into the interview engine. It does not copy that default agent’s prompts. Use HR for communication/group discussion, Domain for knowledge, Practical for scenarios, or Managerial for leadership.')}${field('Tone','<input name="tone" required maxlength="120" class="field-input" placeholder="e.g. neutral, structured, inclusive" value="'+attr(isNew?'':value.tone)+'"/>')}${field('Voice',`<select name="voice_id" class="field-select">${voiceOptions}</select>`,'Available Indian-English live interview voices.')}${field('Opening line',`<textarea name="intro_message" required maxlength="500" class="field-textarea" rows="2">${esc(isNew?'Hello {name}, I\'m your interviewer. It\'s good to meet you.':value.intro_message)}</textarea>`,'Include {name}; it is replaced with the candidate’s first name.')}${field('System prompt',`<textarea name="personality_prompt" required maxlength="4000" class="field-textarea" rows="7" placeholder="Define this agent’s exact interview purpose, question style, boundaries, and follow-up behaviour.">${esc(isNew?'':value.personality_prompt)}</textarea>`,'Controls both question generation and live follow-ups for this agent.')}<div class="modal-actions"><button id="modal-cancel" type="button" class="button button--secondary">Cancel</button><button class="button button--primary">${isNew?'Create agent':'Save changes'}</button></div></form></div>`;
      const close=()=>overlay.innerHTML='';
      qs('#modal-close').onclick=close;qs('#modal-cancel').onclick=close;
      qs('#agent-form').onsubmit=async e=>{
        e.preventDefault();
        const f=new FormData(e.currentTarget),msg=qs('#agent-msg'),btn=e.currentTarget.querySelector('button.button--primary');
        const body={name:f.get('name').trim(),role:f.get('role').trim(),tone:f.get('tone').trim(),voice_id:f.get('voice_id'),intro_message:f.get('intro_message').trim(),personality_prompt:f.get('personality_prompt').trim()};
        if(isNew){body.track=f.get('track');body.make_active=false}
        btn.disabled=true;
        try{
          await api(isNew?'/api/college/agents':`/api/college/agents/${a.id}`,{method:isNew?'POST':'PUT',body});
          close();await refresh();toast('Interviewer saved.');
        }catch(x){msg.className='form-error';msg.textContent=x.message}
        finally{btn.disabled=false}
      };
    }
  }

  // CEO's stated "VOICEDOTS PLACEMENT READINESS INDEX" dashboard: "Student 1
  // -- 92% (green) ... Student 4 -- 54% (red). The college placement
  // officer immediately knows who needs intervention." Backed by GET
  // /api/college/readiness-overview, already worst-first from the server.
  async function renderReadiness(){app.innerHTML=shell({eyebrow:'Placement roadmap',title:'Placement Readiness Index',description:'Every active student’s overall readiness, worst-first, so you know who needs intervention without sorting a spreadsheet.',body:`<div class="toolbar surface"><div class="search-field">⌕<input id="readiness-search" placeholder="Search candidate or roll number…"/></div><span id="readiness-count" class="toolbar-note"></span></div><div id="readiness-results"><div class="skeleton"></div></div>`});bindShell();let data=[];try{const res=await api('/api/college/readiness-overview');data=res.students||[]}catch(e){qs('#readiness-results').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;return}const draw=()=>{const q=qs('#readiness-search').value.toLowerCase();const rows=data.filter(s=>`${s.full_name} ${s.roll_number}`.toLowerCase().includes(q));qs('#readiness-count').textContent=`${rows.length} of ${data.length} students`;qs('#readiness-results').innerHTML=rows.length?`<div class="readiness-heatmap">${rows.map(s=>`<div class="readiness-chip ${s.traffic_light}"><div><strong>${esc(s.full_name)}</strong><span class="small-copy">${esc(s.roll_number)} · ${esc(s.department_code||'—')}${s.interview_sample_count?` · Interview avg of ${s.interview_sample_count}`:''}</span></div><span class="rscore"><span class="rdot ${s.traffic_light}"></span>${s.overall_score==null?'—':Math.round(s.overall_score)+'%'}</span></div>`).join('')}</div>`:empty('No students match this search','Try a different search term.')};draw();qs('#readiness-search').oninput=draw}

  async function renderRoute(){const {path,params}=routeInfo();overlay.innerHTML='';if(!state.me){if(path!='/login')history.replaceState(null,'','#/login');loginPage();return}if(path==='/login'){go('/overview');return}try{if(path==='/overview')return await renderOverview();if(path==='/drives')return await renderDrives();const dm=path.match(/^\/drives\/([^/]+)$/);if(dm)return await renderDrive(dm[1],params);if(path==='/reports')return await renderReports();if(path==='/readiness')return await renderReadiness();if(path==='/students/import')return renderImport();if(path==='/students')return await renderStudents();if(path==='/academic')return await renderAcademic();if(path==='/agents')return await renderAgents();if(path==='/settings')return renderSettings();go('/overview')}catch(e){if(e instanceof ApiError&&e.status===401){state.me=null;applyBrand();go('/login');return}app.innerHTML=state.me?shell({title:'Something went wrong',body:empty('Could not load this page',e.message||'Please try again.')}):'';bindShell()}}
  window.addEventListener('hashchange',renderRoute);hydrate();
})();
